// 项目实战“复刻面试自习室”第 9 关：用户注册、登录和会话。
// 学习卡片由 .sites-runtime/cards/pj-auth-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjAuth:AiLevel={id:'pj-auth',title:'用户注册、登录和会话',summary:'用慢哈希保存密码，用数据库会话和 HttpOnly Cookie 记住登录状态，第一次分出业务逻辑层，页面加上登录、注册和退出',lessons:[
  {title:'这一关做什么：注册、登录和会话',body:'从这一关开始，网站要认识“你是谁”：后面的学习记录、错题本、考试成绩都是每个人自己的。这一关做出账号系统：\n一、注册：POST /api/register，提交用户名和密码，创建账号；\n二、登录：POST /api/login，用户名和密码正确时，服务器发给浏览器一个“会话 Cookie”，之后浏览器每次请求都会自动带上它；\n三、当前用户：GET /api/me，根据 Cookie 返回当前登录的是谁，没登录返回 401；\n四、退出：POST /api/logout，让这个会话失效。\n还会第一次出现“业务逻辑层”（service）：检查用户名格式、加密密码、核对密码、生成会话，这些规则既不属于“处理 HTTP 请求”，也不属于“读写数据库”，单独放一层。页面上也要加上登录、注册和退出。'},
  {title:'密码绝不能明文保存',body:'数据库是可能泄露的：备份文件被人拿走、服务器被入侵、内部人员偷看。如果密码是明文保存的，泄露后所有人的密码都暴露了，而很多人在不同网站用同一个密码，后果更严重。\n正确的做法是只保存密码的“哈希值”：哈希函数把任意内容变成一串固定长度的乱码，同样的输入总得到同样的结果，但从结果几乎不可能反推出原文。登录时，把用户输入的密码用同样的方法算一遍，和数据库里的哈希值比较，一样就说明密码对。\n普通的哈希函数（比如 MD5、SHA-256）不适合用来存密码：它们算得太快了，坏人一秒钟能试几十亿个常见密码。要用专门为密码设计的“慢哈希”：bcrypt、scrypt、Argon2。它们故意算得很慢（每次几十毫秒），对正常登录没影响，对暴力破解却是巨大的障碍。\n它们还会给每个密码加一段随机的“盐”（salt），一起算哈希，盐和哈希值存在一起。这样两个人密码相同，存下来的值也完全不同，坏人没法用事先算好的“密码表”一次破解一大批。'},
  {title:'HTTP 是无状态的：会话和 Cookie',body:'HTTP 协议本身不记得你：每个请求都是独立的，服务器不知道这个请求和上一个是不是同一个人发的。那登录之后，服务器怎么知道后面的请求是“已登录的张三”发的呢？\n常用的办法是“会话”（session）：\n一、登录成功后，服务器生成一个很长的随机字符串，叫会话令牌（token），在数据库的 sessions 表里记下“这个令牌属于张三，7 天后过期”；\n二、服务器在响应头里返回 Set-Cookie: session=令牌，浏览器把它存起来；\n三、之后浏览器访问同一个网站的每个请求，都会自动在请求头里带上 Cookie: session=令牌；\n四、服务器拿令牌去 sessions 表里查，就知道是谁了。退出时删掉这一行，令牌就失效了。\n令牌必须用“密码学安全”的随机数生成器生成（各语言都有专门的函数），而且要足够长，让人猜不到。'},
  {title:'Cookie 的安全选项',body:'设置会话 Cookie 时，要加上几个安全选项：\nHttpOnly：页面上的 JavaScript 读不到这个 Cookie。万一网站有 XSS 漏洞，坏人的脚本也偷不走会话令牌；\nSameSite=Lax：从别的网站发起的“偷偷提交表单”这类请求不会带上这个 Cookie，可以防住大部分 CSRF（跨站请求伪造）攻击；\nPath=/：整个网站都能用这个 Cookie；\nMax-Age：有效期，单位是秒。7 天就是 604800 秒；\nSecure：只在 HTTPS 连接里发送。我们现在本地用的是 HTTP，先不加，第 18 关上线配好 HTTPS 后再加上。\n退出登录时，服务器除了删掉数据库里的会话，还要让浏览器删掉 Cookie：再发一次同名的 Cookie，把有效期设成 0。'},
  {title:'状态码：400、401、409',body:'账号相关的接口会用到几个新的状态码，分清楚它们，前端才能给出准确的提示：\n201 Created：注册成功，创建了一个新资源；\n204 No Content：退出成功，没有内容要返回；\n400 Bad Request：请求内容不合格，比如用户名太短、密码少于 8 位；\n401 Unauthorized：没有登录，或者用户名密码不对；\n409 Conflict：和已有的数据冲突，比如用户名已经被注册了。\n还有一个安全上的细节：登录失败时，不要分别提示“用户名不存在”和“密码错误”，统一说“用户名或密码错误”。否则坏人可以用登录接口试出哪些用户名已经注册了。'},
  {title:'业务逻辑层：service',body:'第 4 关讲分层时说过，业务逻辑层（service）从这一关开始出现。看看“注册”要做的事：\n一、检查用户名：3 到 20 个字符，只能是字母、数字和下划线；检查密码：至少 8 位；\n二、把密码做慢哈希；\n三、保存用户，用户名重复时报“已被注册”。\n第一、二步是“规则”，第三步是“读写数据库”。如果全写在处理请求的层里，规则就和 HTTP 混在一起，以后想在别的地方复用（比如第 15 关用 GitHub 账号登录时自动建号）就很难。所以分成三层：\n处理请求的层：读取 JSON、读写 Cookie、把结果和错误翻译成状态码；\n业务逻辑层：注册、登录、查当前用户、退出这四个功能，以及其中的规则；\n数据访问层：users 表和 sessions 表的增删查。\n业务逻辑层出错时，返回“带有类型的错误”（比如“参数不合格”“用户名已存在”“密码错误”），由处理请求的层决定对应哪个状态码。'},
  {title:'账号接口约定',body:'先把四个接口的约定写清楚，后端、前端和验收脚本都按它来。',code:`POST /api/register   {"username": "tom", "password": "12345678"}
→ 201 {"id": 1, "username": "tom"}
→ 400 {"error": "用户名要 3–20 个字母、数字或下划线，密码至少 8 位"}
→ 409 {"error": "用户名已被注册"}

POST /api/login      {"username": "tom", "password": "12345678"}
→ 200 {"id": 1, "username": "tom"}，响应头 Set-Cookie: session=令牌; Path=/; Max-Age=604800; HttpOnly; SameSite=Lax
→ 401 {"error": "用户名或密码错误"}

GET  /api/me         （请求头带 Cookie: session=令牌）
→ 200 {"id": 1, "username": "tom"}
→ 401 {"error": "请先登录"}

POST /api/logout
→ 204，并让浏览器删掉 session Cookie`,explain:[{at:'POST /api/register',to:'→ 409 {"error": "用户名已被注册"}',text:'注册：正文是 JSON。成功返回 201 和用户（只有 id 和用户名，绝不返回密码或哈希）；格式不对 400；用户名已存在 409。'},{at:'POST /api/login',to:'→ 401 {"error": "用户名或密码错误"}',text:'登录：成功时除了返回用户，还在响应头里设置会话 Cookie，有效期 604800 秒（7 天）。'},{at:'GET  /api/me',to:'→ 401 {"error": "请先登录"}',text:'当前用户：根据 Cookie 里的令牌找到用户。前端用它判断“有没有登录、是谁”。'},{at:'POST /api/logout',to:'→ 204，并让浏览器删掉 session Cookie',text:'退出：删掉服务器上的会话，并让浏览器删掉 Cookie。'}]},
  {title:'任务一：用户和会话的数据访问层',body:'先建 users 和 sessions 两张表，再写它们的增删查：新增用户、按用户名查、保存会话、按令牌查用户、删除会话。用户名重复时，要把数据库的“违反唯一约束”错误翻译成我们自己的“用户名已存在”。',variants:{go:{practice:{steps:['新建 internal/store/users.go，按骨架写，补完 TODO。','go build ./... 确认能编译（接下来两个任务再把它用起来）。'],expect:'go build ./... 没有输出'},code:'// internal/store/users.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n    "strings"\n    "time"\n)\n\ntype User struct {\n    ID           int    `json:"id"`\n    Username     string `json:"username"`\n    PasswordHash string `json:"-"`\n}\n\nvar ErrUsernameTaken = errors.New("username taken")\n\nvar userSchema = []string{\n    `CREATE TABLE IF NOT EXISTS users (\n        id            INTEGER PRIMARY KEY AUTOINCREMENT,\n        username      TEXT NOT NULL UNIQUE,\n        password_hash TEXT NOT NULL,\n        created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS sessions (\n        token      TEXT PRIMARY KEY,\n        user_id    INTEGER NOT NULL REFERENCES users(id),\n        expires_at INTEGER NOT NULL\n    )`,\n}\n\ntype UserStore struct {\n    db *sql.DB\n}\n\n// NewUserStore 建好 users 和 sessions 两张表。\nfunc NewUserStore(db *sql.DB) (*UserStore, error) {\n    for _, stmt := range userSchema {\n        if _, err := db.Exec(stmt); err != nil {\n            return nil, err\n        }\n    }\n    return &UserStore{db: db}, nil\n}\n\n// CreateUser 新增用户，用户名重复时返回 ErrUsernameTaken。\nfunc (s *UserStore) CreateUser(username, hash string) (User, error) {\n    // TODO 1：执行 INSERT INTO users (username, password_hash) VALUES (?, ?)；\n    //         出错且错误信息包含 "UNIQUE" 时返回 ErrUsernameTaken；成功时用 res.LastInsertId() 拿到新用户的 id\n    return User{}, nil\n}\n\n// UserByName 按用户名查找，找不到返回 ErrNotFound。\nfunc (s *UserStore) UserByName(username string) (User, error) {\n    // TODO 2：SELECT id, username, password_hash FROM users WHERE username = ?；sql.ErrNoRows 换成 ErrNotFound\n    return User{}, nil\n}\n\nfunc (s *UserStore) CreateSession(token string, userID int, expires time.Time) error {\n    _, err := s.db.Exec("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)", token, userID, expires.Unix())\n    return err\n}\n\n// UserBySession 按会话令牌查找用户，令牌不存在或已过期时返回 ErrNotFound。\nfunc (s *UserStore) UserBySession(token string) (User, error) {\n    // TODO 3：把 sessions 和 users 两张表连起来查（JOIN users u ON u.id = s.user_id），\n    //         条件是 s.token = ? AND s.expires_at > 当前时间（time.Now().Unix()）；sql.ErrNoRows 换成 ErrNotFound\n    return User{}, nil\n}\n\nfunc (s *UserStore) DeleteSession(token string) error {\n    // TODO 4：DELETE FROM sessions WHERE token = ?\n    return nil\n}',explain:[{at:'// internal/store/users.go',to:'"time"',text:'用户相关的数据访问放在 store 包的一个新文件里，和题目分开。'},{at:'type User struct {',to:'PasswordHash string `json:"-"`',text:'用户结构体。json:"-" 表示转成 JSON 时跳过这个字段：就算哪里不小心把整个 User 返回了，密码哈希也不会出现在接口里。'},{at:'var ErrUsernameTaken = errors.New("username taken")',text:'用户名已存在的错误，业务逻辑层据此告诉用户“已被注册”。'},{at:'var userSchema = []string{',to:'}',text:'两张新表。users：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”更可靠（两个人同时注册同一个名字时，先查再插也可能都成功）。sessions：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（从 1970 年开始的秒数），比较大小很方便。'},{at:'type UserStore struct {',to:'db *sql.DB',text:'用户仓库，和题目仓库共用同一个数据库连接池。'},{at:'func NewUserStore(db *sql.DB) (*UserStore, error) {',to:'return &UserStore{db: db}, nil',text:'逐条执行建表语句，再返回仓库。'},{at:'func (s *UserStore) CreateUser(',to:'return User{}, nil',text:'新增用户，要你补全。'},{at:'func (s *UserStore) UserByName(',to:'return User{}, nil',text:'按用户名查，要你补全。'},{at:'func (s *UserStore) CreateSession(',to:'return err',text:'保存一个会话：令牌、用户 id、过期时间。expires.Unix() 把时间转成秒数。'},{at:'func (s *UserStore) UserBySession(',to:'return User{}, nil',text:'按令牌查用户，要你补全。'},{at:'func (s *UserStore) DeleteSession(',to:'return nil',text:'删除会话，要你补全。'}],solution:{code:'// internal/store/users.go\npackage store\n\nimport (\n    "database/sql"\n    "errors"\n    "strings"\n    "time"\n)\n\ntype User struct {\n    ID           int    `json:"id"`\n    Username     string `json:"username"`\n    PasswordHash string `json:"-"`\n}\n\nvar ErrUsernameTaken = errors.New("username taken")\n\nvar userSchema = []string{\n    `CREATE TABLE IF NOT EXISTS users (\n        id            INTEGER PRIMARY KEY AUTOINCREMENT,\n        username      TEXT NOT NULL UNIQUE,\n        password_hash TEXT NOT NULL,\n        created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )`,\n    `CREATE TABLE IF NOT EXISTS sessions (\n        token      TEXT PRIMARY KEY,\n        user_id    INTEGER NOT NULL REFERENCES users(id),\n        expires_at INTEGER NOT NULL\n    )`,\n}\n\ntype UserStore struct {\n    db *sql.DB\n}\n\n// NewUserStore 建好 users 和 sessions 两张表。\nfunc NewUserStore(db *sql.DB) (*UserStore, error) {\n    for _, stmt := range userSchema {\n        if _, err := db.Exec(stmt); err != nil {\n            return nil, err\n        }\n    }\n    return &UserStore{db: db}, nil\n}\n\n// CreateUser 新增用户，用户名重复时返回 ErrUsernameTaken。\nfunc (s *UserStore) CreateUser(username, hash string) (User, error) {\n    res, err := s.db.Exec("INSERT INTO users (username, password_hash) VALUES (?, ?)", username, hash)\n    if err != nil {\n        if strings.Contains(err.Error(), "UNIQUE") {\n            return User{}, ErrUsernameTaken\n        }\n        return User{}, err\n    }\n    id, err := res.LastInsertId()\n    return User{ID: int(id), Username: username, PasswordHash: hash}, err\n}\n\n// UserByName 按用户名查找，找不到返回 ErrNotFound。\nfunc (s *UserStore) UserByName(username string) (User, error) {\n    var u User\n    err := s.db.QueryRow("SELECT id, username, password_hash FROM users WHERE username = ?", username).\n        Scan(&u.ID, &u.Username, &u.PasswordHash)\n    if errors.Is(err, sql.ErrNoRows) {\n        return User{}, ErrNotFound\n    }\n    return u, err\n}\n\nfunc (s *UserStore) CreateSession(token string, userID int, expires time.Time) error {\n    _, err := s.db.Exec("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)", token, userID, expires.Unix())\n    return err\n}\n\n// UserBySession 按会话令牌查找用户，令牌不存在或已过期时返回 ErrNotFound。\nfunc (s *UserStore) UserBySession(token string) (User, error) {\n    var u User\n    err := s.db.QueryRow(`SELECT u.id, u.username, u.password_hash FROM sessions s\n        JOIN users u ON u.id = s.user_id WHERE s.token = ? AND s.expires_at > ?`, token, time.Now().Unix()).\n        Scan(&u.ID, &u.Username, &u.PasswordHash)\n    if errors.Is(err, sql.ErrNoRows) {\n        return User{}, ErrNotFound\n    }\n    return u, err\n}\n\nfunc (s *UserStore) DeleteSession(token string) error {\n    _, err := s.db.Exec("DELETE FROM sessions WHERE token = ?", token)\n    return err\n}',explain:[{at:'// internal/store/users.go',to:'"time"',text:'用户相关的数据访问放在 store 包的一个新文件里，和题目分开。'},{at:'type User struct {',to:'PasswordHash string `json:"-"`',text:'用户结构体。json:"-" 表示转成 JSON 时跳过这个字段：就算哪里不小心把整个 User 返回了，密码哈希也不会出现在接口里。'},{at:'var ErrUsernameTaken = errors.New("username taken")',text:'用户名已存在的错误，业务逻辑层据此告诉用户“已被注册”。'},{at:'var userSchema = []string{',to:'}',text:'两张新表。users：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”更可靠（两个人同时注册同一个名字时，先查再插也可能都成功）。sessions：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（从 1970 年开始的秒数），比较大小很方便。'},{at:'type UserStore struct {',to:'db *sql.DB',text:'用户仓库，和题目仓库共用同一个数据库连接池。'},{at:'func NewUserStore(db *sql.DB) (*UserStore, error) {',to:'return &UserStore{db: db}, nil',text:'逐条执行建表语句，再返回仓库。'},{at:'func (s *UserStore) CreateUser(',to:'res, err := s.db.Exec(',text:'插入新用户。'},{at:'if err != nil {',to:'return User{}, err',text:'违反 UNIQUE 约束时，SQLite 的错误信息里有 UNIQUE constraint failed，翻译成我们自己的 ErrUsernameTaken；其他错误原样返回。'},{at:'id, err := res.LastInsertId()',to:'return User{ID: int(id), Username: username, PasswordHash: hash}, err',text:'LastInsertId 取得数据库刚自动生成的 id。'},{at:'func (s *UserStore) UserByName(',to:'return u, err',text:'按用户名查一行，没找到换成 ErrNotFound。'},{at:'func (s *UserStore) CreateSession(',to:'return err',text:'保存一个会话：令牌、用户 id、过期时间。expires.Unix() 把时间转成秒数。'},{at:'func (s *UserStore) UserBySession(',to:'Scan(&u.ID, &u.Username, &u.PasswordHash)',text:'JOIN 把两张表按条件连起来查：sessions 表起别名 s，users 表起别名 u，令牌匹配并且还没过期，就取出对应的用户。'},{at:'if errors.Is(err, sql.ErrNoRows) {',to:'return u, err',text:'令牌不存在或者过期了，都当作没找到。'},{at:'func (s *UserStore) DeleteSession(',to:'return err',text:'退出时删掉这个会话。'}]}},java:{practice:{steps:['按代码第一部分修改 schema.sql。','新建 model/User.java 和 repository/UserRepository.java，补完 TODO。'],expect:'IDEA 里没有红色报错即可，接下来两个任务再把它用起来'},code:'-- src/main/resources/schema.sql：在 questions 表后面加上\nCREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n);\n\n// model/User.java\npackage com.example.zixishi.model;\n\nimport com.fasterxml.jackson.annotation.JsonIgnore;\n\npublic record User(int id, String username, @JsonIgnore String passwordHash) {}\n\n// repository/UserRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.User;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DataIntegrityViolationException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.core.RowMapper;\nimport org.springframework.stereotype.Repository;\n\n@Repository\npublic class UserRepository {\n\n    public static class UsernameTakenException extends RuntimeException {}\n\n    private static final RowMapper<User> MAPPER =\n        (rs, i) -> new User(rs.getInt("id"), rs.getString("username"), rs.getString("password_hash"));\n\n    private final JdbcTemplate jdbc;\n\n    public UserRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    // 新增用户；用户名重复时抛出 UsernameTakenException\n    public User create(String username, String passwordHash) {\n        // TODO 1：用 jdbc.update 执行 INSERT INTO users (username, password_hash) VALUES (?, ?)，\n        //         捕获 DataIntegrityViolationException，改为抛出 UsernameTakenException；\n        //         成功后用 findByUsername(username).orElseThrow() 查出新用户返回\n        return null;\n    }\n\n    public Optional<User> findByUsername(String username) {\n        // TODO 2：SELECT id, username, password_hash FROM users WHERE username = ?\n        return Optional.empty();\n    }\n\n    public void createSession(String token, int userId, Instant expiresAt) {\n        jdbc.update("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)",\n            token, userId, expiresAt.getEpochSecond());\n    }\n\n    // 按令牌查找没过期的会话对应的用户\n    public Optional<User> findBySession(String token) {\n        // TODO 3：sessions 表和 users 表连起来查：JOIN users u ON u.id = s.user_id，\n        //         条件是 s.token = ? AND s.expires_at > 当前时间（Instant.now().getEpochSecond()）\n        return Optional.empty();\n    }\n\n    public void deleteSession(String token) {\n        // TODO 4：DELETE FROM sessions WHERE token = ?\n    }\n}',explain:[{at:'-- src/main/resources/schema.sql',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:');',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（秒），比较大小很方便。'},{at:'// model/User.java',to:'public record User(int id, String username, @JsonIgnore String passwordHash) {}',text:'用户 record。@JsonIgnore 表示转成 JSON 时跳过这个字段：就算哪里不小心把整个 User 返回了，密码哈希也不会出现在接口里。Jackson 3 仍然使用 com.fasterxml.jackson.annotation 这个包里的注解。'},{at:'// repository/UserRepository.java',to:'import org.springframework.stereotype.Repository;',text:'用户仓库。DataIntegrityViolationException 是 Spring 对“违反数据库约束”这类错误的统一包装。'},{at:'@Repository',to:'public static class UsernameTakenException extends RuntimeException {}',text:'在仓库里定义一个异常：用户名已存在。继承 RuntimeException 的异常不需要在方法上声明 throws。'},{at:'private static final RowMapper<User> MAPPER =',to:'(rs, i) -> new User(',text:'把一行结果变成 User。'},{at:'private final JdbcTemplate jdbc;',to:'this.jdbc = jdbc;',text:'注入 JdbcTemplate。'},{at:'public User create(',to:'return null;',text:'新增用户，要你补全。'},{at:'public Optional<User> findByUsername(',to:'return Optional.empty();',text:'按用户名查，要你补全。'},{at:'public void createSession(',to:'token, userId, expiresAt.getEpochSecond());',text:'保存一个会话。getEpochSecond 把时间转成从 1970 年开始的秒数。'},{at:'public Optional<User> findBySession(',to:'return Optional.empty();',text:'按令牌查用户，要你补全。'},{at:'public void deleteSession(',to:'}',text:'删除会话，要你补全。'}],solution:{code:'-- src/main/resources/schema.sql：在 questions 表后面加上\nCREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n);\n\n// model/User.java\npackage com.example.zixishi.model;\n\nimport com.fasterxml.jackson.annotation.JsonIgnore;\n\npublic record User(int id, String username, @JsonIgnore String passwordHash) {}\n\n// repository/UserRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.User;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DataIntegrityViolationException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.core.RowMapper;\nimport org.springframework.stereotype.Repository;\n\n@Repository\npublic class UserRepository {\n\n    public static class UsernameTakenException extends RuntimeException {}\n\n    private static final RowMapper<User> MAPPER =\n        (rs, i) -> new User(rs.getInt("id"), rs.getString("username"), rs.getString("password_hash"));\n\n    private final JdbcTemplate jdbc;\n\n    public UserRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    public User create(String username, String passwordHash) {\n        try {\n            jdbc.update("INSERT INTO users (username, password_hash) VALUES (?, ?)", username, passwordHash);\n        } catch (DataIntegrityViolationException e) {\n            throw new UsernameTakenException();\n        }\n        return findByUsername(username).orElseThrow();\n    }\n\n    public Optional<User> findByUsername(String username) {\n        return jdbc.query("SELECT id, username, password_hash FROM users WHERE username = ?", MAPPER, username)\n            .stream().findFirst();\n    }\n\n    public void createSession(String token, int userId, Instant expiresAt) {\n        jdbc.update("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)",\n            token, userId, expiresAt.getEpochSecond());\n    }\n\n    public Optional<User> findBySession(String token) {\n        return jdbc.query("""\n            SELECT u.id, u.username, u.password_hash FROM sessions s JOIN users u ON u.id = s.user_id\n            WHERE s.token = ? AND s.expires_at > ?""", MAPPER, token, Instant.now().getEpochSecond())\n            .stream().findFirst();\n    }\n\n    public void deleteSession(String token) {\n        jdbc.update("DELETE FROM sessions WHERE token = ?", token);\n    }\n}',explain:[{at:'-- src/main/resources/schema.sql',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:');',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（秒），比较大小很方便。'},{at:'// model/User.java',to:'public record User(int id, String username, @JsonIgnore String passwordHash) {}',text:'用户 record。@JsonIgnore 表示转成 JSON 时跳过这个字段：就算哪里不小心把整个 User 返回了，密码哈希也不会出现在接口里。Jackson 3 仍然使用 com.fasterxml.jackson.annotation 这个包里的注解。'},{at:'// repository/UserRepository.java',to:'import org.springframework.stereotype.Repository;',text:'用户仓库。DataIntegrityViolationException 是 Spring 对“违反数据库约束”这类错误的统一包装。'},{at:'@Repository',to:'public static class UsernameTakenException extends RuntimeException {}',text:'在仓库里定义一个异常：用户名已存在。继承 RuntimeException 的异常不需要在方法上声明 throws。'},{at:'private static final RowMapper<User> MAPPER =',to:'(rs, i) -> new User(',text:'把一行结果变成 User。'},{at:'private final JdbcTemplate jdbc;',to:'this.jdbc = jdbc;',text:'注入 JdbcTemplate。'},{at:'public User create(',to:'return findByUsername(username).orElseThrow();',text:'插入新用户，违反 UNIQUE 约束时换成我们自己的异常；成功后再查一次，拿到数据库生成的 id。'},{at:'public Optional<User> findByUsername(',to:'.stream().findFirst();',text:'按用户名查，没有时是空的 Optional。'},{at:'public void createSession(',to:'token, userId, expiresAt.getEpochSecond());',text:'保存一个会话。getEpochSecond 把时间转成从 1970 年开始的秒数。'},{at:'public Optional<User> findBySession(',to:'.stream().findFirst();',text:'三个双引号是 Java 的文本块，可以写多行字符串。JOIN 把两张表按条件连起来查：令牌匹配并且还没过期，就取出对应的用户。'},{at:'public void deleteSession(',to:'jdbc.update("DELETE FROM sessions WHERE token = ?", token);',text:'退出时删掉这个会话。'}]}},node:{practice:{steps:['按代码第一部分修改 src/db/database.js，加上两张新表。','新建 src/db/users.js（第二部分），补完 TODO。'],expect:'文件保存好即可，接下来两个任务再把它用起来'},code:'// src/db/database.js：在建 questions 表的 db.exec 后面再加一段\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n  );\n`);\n\n// src/db/users.js\nconst { db } = require("./database");\n\nclass UsernameTakenError extends Error {}\n\n// 新增用户，返回 { id, username }；用户名重复时抛出 UsernameTakenError\nfunction createUser(username, passwordHash) {\n  // TODO 1：执行 INSERT INTO users (username, password_hash) VALUES (?, ?)（用 .run）；\n  //         新用户的 id 是 result.lastInsertRowid（转成 Number）；\n  //         捕获错误，err.code 是 "SQLITE_CONSTRAINT_UNIQUE" 时改为抛出 UsernameTakenError\n}\n\n// 按用户名查找，返回 { id, username, password_hash }，没有时是 undefined\nfunction findUserByName(username) {\n  // TODO 2\n}\n\nfunction createSession(token, userId, expiresAt) {\n  db.prepare("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)").run(token, userId, expiresAt);\n}\n\n// 按令牌查找用户（只要没过期的），返回 { id, username } 或 undefined\nfunction findUserBySession(token) {\n  // TODO 3：sessions 表和 users 表连起来查：JOIN users u ON u.id = s.user_id，\n  //         条件是 s.token = ? AND s.expires_at > 当前时间（Date.now()）\n}\n\nfunction deleteSession(token) {\n  // TODO 4：DELETE FROM sessions WHERE token = ?\n}\n\nmodule.exports = { UsernameTakenError, createUser, findUserByName, createSession, findUserBySession, deleteSession };',explain:[{at:'// src/db/database.js',to:'db.exec(`',text:'db.exec 可以一次执行多条用分号隔开的语句。'},{at:'CREATE TABLE IF NOT EXISTS users (',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:'`);',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的毫秒时间戳，比较大小很方便。'},{at:'// src/db/users.js',to:'const { db } = require("./database");',text:'用户相关的数据访问放在新文件里。'},{at:'class UsernameTakenError extends Error {}',text:'自定义一种错误：用户名已存在。extends Error 表示它是一种错误，上层可以用 instanceof 判断是不是它。'},{at:'function createUser(',text:'新增用户，要你补全。'},{at:'function findUserByName(',text:'按用户名查，要你补全。'},{at:'function findUserBySession(',text:'按令牌查用户，要你补全。'},{at:'function deleteSession(',text:'删除会话，要你补全。'},{at:'function createSession(',to:'db.prepare("INSERT INTO sessions',text:'保存一个会话：令牌、用户 id、过期时间。'},{at:'module.exports = {',text:'导出错误类型和五个函数。'}],solution:{code:'// src/db/database.js：在建 questions 表的 db.exec 后面再加一段\ndb.exec(`\n  CREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n  );\n  CREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n  );\n`);\n\n// src/db/users.js\nconst { db } = require("./database");\n\nclass UsernameTakenError extends Error {}\n\nfunction createUser(username, passwordHash) {\n  try {\n    const result = db\n      .prepare("INSERT INTO users (username, password_hash) VALUES (?, ?)")\n      .run(username, passwordHash);\n    return { id: Number(result.lastInsertRowid), username };\n  } catch (err) {\n    if (err.code === "SQLITE_CONSTRAINT_UNIQUE") throw new UsernameTakenError();\n    throw err;\n  }\n}\n\nfunction findUserByName(username) {\n  return db.prepare("SELECT id, username, password_hash FROM users WHERE username = ?").get(username);\n}\n\nfunction createSession(token, userId, expiresAt) {\n  db.prepare("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)").run(token, userId, expiresAt);\n}\n\nfunction findUserBySession(token) {\n  return db\n    .prepare(`SELECT u.id, u.username FROM sessions s JOIN users u ON u.id = s.user_id\n              WHERE s.token = ? AND s.expires_at > ?`)\n    .get(token, Date.now());\n}\n\nfunction deleteSession(token) {\n  db.prepare("DELETE FROM sessions WHERE token = ?").run(token);\n}\n\nmodule.exports = { UsernameTakenError, createUser, findUserByName, createSession, findUserBySession, deleteSession };',explain:[{at:'// src/db/database.js',to:'db.exec(`',text:'db.exec 可以一次执行多条用分号隔开的语句。'},{at:'CREATE TABLE IF NOT EXISTS users (',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:'`);',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的毫秒时间戳，比较大小很方便。'},{at:'// src/db/users.js',to:'const { db } = require("./database");',text:'用户相关的数据访问放在新文件里。'},{at:'class UsernameTakenError extends Error {}',text:'自定义一种错误：用户名已存在。extends Error 表示它是一种错误，上层可以用 instanceof 判断是不是它。'},{at:'function createUser(',to:'return { id: Number(result.lastInsertRowid), username };',text:'run 执行插入，返回的 lastInsertRowid 是数据库刚自动生成的 id（可能是 BigInt 类型，用 Number 转成普通数字）。'},{at:'} catch (err) {',to:'throw err;',text:'违反 UNIQUE 约束时，better-sqlite3 的错误代码是 SQLITE_CONSTRAINT_UNIQUE，换成我们自己的错误类型；其他错误原样抛出。'},{at:'function findUserByName(',to:'return db.prepare(',text:'按用户名查一行，带上密码哈希，登录时要用它核对。'},{at:'function createSession(',to:'db.prepare("INSERT INTO sessions',text:'保存一个会话：令牌、用户 id、过期时间。'},{at:'function findUserBySession(',to:'.get(token, Date.now());',text:'JOIN 把两张表按条件连起来查：sessions 起别名 s，users 起别名 u，令牌匹配并且还没过期，就取出对应的用户。Date.now() 是当前时间的毫秒数。'},{at:'function deleteSession(',to:'db.prepare("DELETE FROM sessions',text:'退出时删掉这个会话。'},{at:'module.exports = {',text:'导出错误类型和五个函数。'}]}},python:{practice:{steps:['按代码第一部分修改 app/database.py。','新建 app/users.py（第二部分），补完 TODO。','删掉 data/zixishi.db 再启动一次也可以，三张表都会重新建好、题目重新导入；不删也没关系，IF NOT EXISTS 会补建新表。'],expect:'启动不报错即可，接下来两个任务再把它用起来'},code:'# app/database.py：SCHEMA 换成下面三张表，init_db 里的 conn.execute(SCHEMA) 改成 conn.executescript(SCHEMA)，\n# 再加上 execute 函数\nSCHEMA = """\nCREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n);\nCREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n);\n"""\n\n\ndef execute(sql, params=()):\n    """执行一条写入语句（INSERT、DELETE），返回新插入行的 id"""\n    with closing(connect()) as conn:\n        with conn:\n            return conn.execute(sql, params).lastrowid\n\n# app/users.py\nimport sqlite3\nimport time\n\nfrom app.database import execute, query_one\n\n\nclass UsernameTaken(Exception):\n    """用户名已被注册"""\n\n\ndef create_user(username, password_hash):\n    """新增用户，返回 {"id", "username"}；用户名重复时抛出 UsernameTaken"""\n    # TODO 1：用 execute 执行 INSERT INTO users (username, password_hash) VALUES (?, ?)，得到新 id；\n    #         捕获 sqlite3.IntegrityError（违反 UNIQUE 约束），改为抛出 UsernameTaken\n    return None\n\n\ndef find_user_by_name(username):\n    """按用户名查找，返回 {"id", "username", "password_hash"} 或 None"""\n    # TODO 2\n    return None\n\n\ndef create_session(token, user_id, expires_at):\n    execute("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)", (token, user_id, expires_at))\n\n\ndef find_user_by_session(token):\n    """按令牌查找没过期的会话对应的用户，返回 {"id", "username"} 或 None"""\n    # TODO 3：sessions 表和 users 表连起来查：JOIN users u ON u.id = s.user_id，\n    #         条件是 s.token = ? AND s.expires_at > 当前时间（int(time.time())）\n    return None\n\n\ndef delete_session(token):\n    # TODO 4：DELETE FROM sessions WHERE token = ?\n    pass',explain:[{at:'SCHEMA = """',to:');',text:'题目表不变。多条语句要用 executescript 执行，execute 一次只能执行一条。'},{at:'CREATE TABLE IF NOT EXISTS users (',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:'"""',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（从 1970 年开始的秒数），比较大小很方便。'},{at:'def execute(sql, params=()):',to:'return conn.execute(sql, params).lastrowid',text:'写入用的通用函数：with conn 开一个事务，成功就提交。lastrowid 是数据库刚自动生成的 id。'},{at:'# app/users.py',to:'from app.database import execute, query_one',text:'用户相关的数据访问放在新文件里。'},{at:'class UsernameTaken(Exception):',to:'"""用户名已被注册"""',text:'自定义一种异常：用户名已存在。继承 Exception，上层可以专门捕获它。类里只有一段说明文字也是合法的。'},{at:'def create_user(',to:'return None',text:'新增用户，要你补全。'},{at:'def find_user_by_name(',to:'return None',text:'按用户名查，要你补全。'},{at:'def create_session(',to:'execute("INSERT INTO sessions',text:'保存一个会话：令牌、用户 id、过期时间。'},{at:'def find_user_by_session(',to:'return None',text:'按令牌查用户，要你补全。'},{at:'def delete_session(',to:'pass',text:'删除会话，要你补全。'}],solution:{code:'# app/database.py：SCHEMA 换成下面三张表，init_db 里的 conn.execute(SCHEMA) 改成 conn.executescript(SCHEMA)，\n# 再加上 execute 函数\nSCHEMA = """\nCREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n);\nCREATE TABLE IF NOT EXISTS users (\n    id            INTEGER PRIMARY KEY AUTOINCREMENT,\n    username      TEXT NOT NULL UNIQUE,\n    password_hash TEXT NOT NULL,\n    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS sessions (\n    token      TEXT PRIMARY KEY,\n    user_id    INTEGER NOT NULL REFERENCES users(id),\n    expires_at INTEGER NOT NULL\n);\n"""\n\n\ndef execute(sql, params=()):\n    """执行一条写入语句（INSERT、DELETE），返回新插入行的 id"""\n    with closing(connect()) as conn:\n        with conn:\n            return conn.execute(sql, params).lastrowid\n\n# app/users.py\nimport sqlite3\nimport time\n\nfrom app.database import execute, query_one\n\n\nclass UsernameTaken(Exception):\n    """用户名已被注册"""\n\n\ndef create_user(username, password_hash):\n    try:\n        uid = execute("INSERT INTO users (username, password_hash) VALUES (?, ?)", (username, password_hash))\n    except sqlite3.IntegrityError:\n        raise UsernameTaken() from None\n    return {"id": uid, "username": username}\n\n\ndef find_user_by_name(username):\n    return query_one("SELECT id, username, password_hash FROM users WHERE username = ?", (username,))\n\n\ndef create_session(token, user_id, expires_at):\n    execute("INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)", (token, user_id, expires_at))\n\n\ndef find_user_by_session(token):\n    return query_one(\n        "SELECT u.id, u.username FROM sessions s JOIN users u ON u.id = s.user_id "\n        "WHERE s.token = ? AND s.expires_at > ?",\n        (token, int(time.time())),\n    )\n\n\ndef delete_session(token):\n    execute("DELETE FROM sessions WHERE token = ?", (token,))',explain:[{at:'SCHEMA = """',to:');',text:'题目表不变。多条语句要用 executescript 执行，execute 一次只能执行一条。'},{at:'CREATE TABLE IF NOT EXISTS users (',to:');',text:'用户表：AUTOINCREMENT 让 id 自动递增；UNIQUE 让数据库保证用户名不重复，这比“先查一下再插入”可靠（两个人同时注册同一个名字时，先查再插也可能都成功）；密码只存哈希值。'},{at:'CREATE TABLE IF NOT EXISTS sessions (',to:'"""',text:'会话表：一个令牌对应一个用户，REFERENCES 说明 user_id 指向 users 表的 id；expires_at 存过期时间的 Unix 时间戳（从 1970 年开始的秒数），比较大小很方便。'},{at:'def execute(sql, params=()):',to:'return conn.execute(sql, params).lastrowid',text:'写入用的通用函数：with conn 开一个事务，成功就提交。lastrowid 是数据库刚自动生成的 id。'},{at:'# app/users.py',to:'from app.database import execute, query_one',text:'用户相关的数据访问放在新文件里。'},{at:'class UsernameTaken(Exception):',to:'"""用户名已被注册"""',text:'自定义一种异常：用户名已存在。继承 Exception，上层可以专门捕获它。类里只有一段说明文字也是合法的。'},{at:'def create_user(',to:'return {"id": uid, "username": username}',text:'插入新用户。违反 UNIQUE 约束时 sqlite3 抛出 IntegrityError，换成我们自己的 UsernameTaken；from None 表示不把原来的异常附带上。'},{at:'def find_user_by_name(',to:'return query_one(',text:'按用户名查一行，带上密码哈希，登录时要用它核对。'},{at:'def create_session(',to:'execute("INSERT INTO sessions',text:'保存一个会话：令牌、用户 id、过期时间。'},{at:'def find_user_by_session(',to:'(token, int(time.time())),',text:'JOIN 把两张表按条件连起来查：sessions 起别名 s，users 起别名 u，令牌匹配并且还没过期，就取出对应的用户。'},{at:'def delete_session(',to:'execute("DELETE FROM sessions',text:'退出时删掉这个会话。'}]}}}},
  {title:'任务二：账号的业务逻辑层',body:'新建业务逻辑层，实现注册、登录、查当前用户、退出四个功能：检查用户名和密码的格式、用慢哈希保存密码、核对密码、生成安全的随机令牌。出错时返回带类型的错误，由上层翻译成状态码。',variants:{go:{practice:{steps:['在项目根目录运行 go get golang.org/x/crypto/bcrypt 安装 bcrypt。','新建 internal/service/auth.go，按骨架写，补完 TODO。','go build ./... 确认能编译。'],expect:'go build ./... 没有输出'},code:'// internal/service/auth.go\npackage service\n\nimport (\n    "crypto/rand"\n    "encoding/hex"\n    "errors"\n    "regexp"\n    "time"\n\n    "golang.org/x/crypto/bcrypt"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrInvalidInput   = errors.New("用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n    ErrBadCredentials = errors.New("用户名或密码错误")\n    ErrNotLoggedIn    = errors.New("请先登录")\n)\n\nconst SessionTTL = 7 * 24 * time.Hour\n\nvar usernamePattern = regexp.MustCompile(`^[A-Za-z0-9_]{3,20}$`)\n\ntype AuthService struct {\n    users *store.UserStore\n}\n\nfunc NewAuthService(users *store.UserStore) *AuthService {\n    return &AuthService{users: users}\n}\n\nfunc newToken() (string, error) {\n    b := make([]byte, 32)\n    if _, err := rand.Read(b); err != nil {\n        return "", err\n    }\n    return hex.EncodeToString(b), nil\n}\n\n// Register 检查用户名和密码，保存哈希后的密码。\nfunc (a *AuthService) Register(username, password string) (store.User, error) {\n    // TODO 1：用户名不符合 usernamePattern 或密码少于 8 位时返回 ErrInvalidInput\n    // TODO 2：用 bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost) 算出哈希，\n    //         再调用 a.users.CreateUser(用户名, string(哈希))\n    return store.User{}, nil\n}\n\n// Login 核对密码，成功时创建会话，返回令牌。\nfunc (a *AuthService) Login(username, password string) (string, store.User, error) {\n    // TODO 3：用 a.users.UserByName 找用户，找不到返回 ErrBadCredentials\n    // TODO 4：用 bcrypt.CompareHashAndPassword(哈希, 密码) 核对，不对返回 ErrBadCredentials\n    // TODO 5：用 newToken() 生成令牌，a.users.CreateSession(令牌, 用户 id, time.Now().Add(SessionTTL))，返回令牌和用户\n    return "", store.User{}, nil\n}\n\n// CurrentUser 按令牌找到当前用户，没有或过期时返回 ErrNotLoggedIn。\nfunc (a *AuthService) CurrentUser(token string) (store.User, error) {\n    // TODO 6：令牌为空或 a.users.UserBySession 返回 store.ErrNotFound 时返回 ErrNotLoggedIn\n    return store.User{}, nil\n}\n\nfunc (a *AuthService) Logout(token string) error {\n    return a.users.DeleteSession(token)\n}',explain:[{at:'// internal/service/auth.go',to:'"zixishi/internal/store"',text:'新建 service 包。crypto/rand 是密码学安全的随机数；regexp 是正则表达式；bcrypt 是慢哈希算法，用 go get golang.org/x/crypto 安装。'},{at:'var (',to:'ErrNotLoggedIn    = errors.New("请先登录")',text:'业务逻辑层的三种错误，错误信息直接写成给用户看的中文，处理请求的层会决定它们对应的状态码。'},{at:'const SessionTTL = 7 * 24 * time.Hour',text:'会话有效期 7 天。TTL 是 time to live（存活时间）的缩写。'},{at:'var usernamePattern = regexp.MustCompile(`^[A-Za-z0-9_]{3,20}$`)',text:'用户名规则的正则表达式：^ 和 $ 表示从头到尾都要匹配；[A-Za-z0-9_] 是字母、数字、下划线中的一个；{3,20} 表示重复 3 到 20 次。'},{at:'type AuthService struct {',to:'return &AuthService{users: users}',text:'业务逻辑层的对象，依赖数据访问层的 UserStore。'},{at:'func newToken() (string, error) {',to:'return hex.EncodeToString(b), nil',text:'生成会话令牌：32 个随机字节，转成 64 个十六进制字符。crypto/rand 的随机数无法预测，千万不要用 math/rand。'},{at:'func (a *AuthService) Register(',to:'return store.User{}, nil',text:'注册，要你补全。'},{at:'func (a *AuthService) Login(',to:'return "", store.User{}, nil',text:'登录，要你补全。'},{at:'func (a *AuthService) CurrentUser(',to:'return store.User{}, nil',text:'查当前用户，要你补全。'},{at:'func (a *AuthService) Logout(',to:'return a.users.DeleteSession(token)',text:'退出：删掉这个会话。'}],solution:{code:'// internal/service/auth.go\npackage service\n\nimport (\n    "crypto/rand"\n    "encoding/hex"\n    "errors"\n    "regexp"\n    "time"\n\n    "golang.org/x/crypto/bcrypt"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrInvalidInput   = errors.New("用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n    ErrBadCredentials = errors.New("用户名或密码错误")\n    ErrNotLoggedIn    = errors.New("请先登录")\n)\n\nconst SessionTTL = 7 * 24 * time.Hour\n\nvar usernamePattern = regexp.MustCompile(`^[A-Za-z0-9_]{3,20}$`)\n\ntype AuthService struct {\n    users *store.UserStore\n}\n\nfunc NewAuthService(users *store.UserStore) *AuthService {\n    return &AuthService{users: users}\n}\n\nfunc newToken() (string, error) {\n    b := make([]byte, 32)\n    if _, err := rand.Read(b); err != nil {\n        return "", err\n    }\n    return hex.EncodeToString(b), nil\n}\n\n// Register 检查用户名和密码，保存哈希后的密码。\nfunc (a *AuthService) Register(username, password string) (store.User, error) {\n    if !usernamePattern.MatchString(username) || len(password) < 8 {\n        return store.User{}, ErrInvalidInput\n    }\n    hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)\n    if err != nil {\n        return store.User{}, err\n    }\n    return a.users.CreateUser(username, string(hash))\n}\n\n// Login 核对密码，成功时创建会话，返回令牌。\nfunc (a *AuthService) Login(username, password string) (string, store.User, error) {\n    u, err := a.users.UserByName(username)\n    if errors.Is(err, store.ErrNotFound) {\n        return "", store.User{}, ErrBadCredentials\n    }\n    if err != nil {\n        return "", store.User{}, err\n    }\n    if bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(password)) != nil {\n        return "", store.User{}, ErrBadCredentials\n    }\n    token, err := newToken()\n    if err != nil {\n        return "", store.User{}, err\n    }\n    err = a.users.CreateSession(token, u.ID, time.Now().Add(SessionTTL))\n    return token, u, err\n}\n\n// CurrentUser 按令牌找到当前用户，没有或过期时返回 ErrNotLoggedIn。\nfunc (a *AuthService) CurrentUser(token string) (store.User, error) {\n    if token == "" {\n        return store.User{}, ErrNotLoggedIn\n    }\n    u, err := a.users.UserBySession(token)\n    if errors.Is(err, store.ErrNotFound) {\n        return store.User{}, ErrNotLoggedIn\n    }\n    return u, err\n}\n\nfunc (a *AuthService) Logout(token string) error {\n    return a.users.DeleteSession(token)\n}',explain:[{at:'// internal/service/auth.go',to:'"zixishi/internal/store"',text:'新建 service 包。crypto/rand 是密码学安全的随机数；regexp 是正则表达式；bcrypt 是慢哈希算法，用 go get golang.org/x/crypto 安装。'},{at:'var (',to:'ErrNotLoggedIn    = errors.New("请先登录")',text:'业务逻辑层的三种错误，错误信息直接写成给用户看的中文，处理请求的层会决定它们对应的状态码。'},{at:'const SessionTTL = 7 * 24 * time.Hour',text:'会话有效期 7 天。TTL 是 time to live（存活时间）的缩写。'},{at:'var usernamePattern = regexp.MustCompile(`^[A-Za-z0-9_]{3,20}$`)',text:'用户名规则的正则表达式：^ 和 $ 表示从头到尾都要匹配；[A-Za-z0-9_] 是字母、数字、下划线中的一个；{3,20} 表示重复 3 到 20 次。'},{at:'type AuthService struct {',to:'return &AuthService{users: users}',text:'业务逻辑层的对象，依赖数据访问层的 UserStore。'},{at:'func newToken() (string, error) {',to:'return hex.EncodeToString(b), nil',text:'生成会话令牌：32 个随机字节，转成 64 个十六进制字符。crypto/rand 的随机数无法预测，千万不要用 math/rand。'},{at:'func (a *AuthService) Register(',to:'return store.User{}, ErrInvalidInput',text:'先按规则检查，不合格直接返回，不碰数据库。'},{at:'hash, err := bcrypt.GenerateFromPassword(',to:'return a.users.CreateUser(username, string(hash))',text:'bcrypt 会自动生成随机盐，结果里同时包含算法、成本、盐和哈希值，存这一个字符串就够了。DefaultCost 是“慢的程度”，数字每加 1，计算时间翻一倍。用户名重复时 CreateUser 返回 ErrUsernameTaken，原样交给上层。'},{at:'func (a *AuthService) Login(',to:'return "", store.User{}, err',text:'找用户。找不到时返回的是“用户名或密码错误”，不暴露这个用户名是否存在。'},{at:'if bcrypt.CompareHashAndPassword(',to:'return "", store.User{}, ErrBadCredentials',text:'CompareHashAndPassword 从存下的值里取出盐，用同样的方法算一遍再比较，返回 nil 表示密码正确。'},{at:'token, err := newToken()',to:'return token, u, err',text:'生成令牌，保存会话，7 天后过期。'},{at:'func (a *AuthService) CurrentUser(',to:'return u, err',text:'没有令牌、令牌无效或过期，都是“请先登录”。'},{at:'func (a *AuthService) Logout(',to:'return a.users.DeleteSession(token)',text:'退出：删掉这个会话。'}]}},java:{practice:{steps:['按代码第一部分修改 pom.xml，点 Load Maven Changes。','新建 service/AuthService.java，补完 TODO。'],expect:'IDEA 里没有红色报错即可，下一个任务把它接到控制器上'},code:'<!-- pom.xml 的 <dependencies> 里加上（只用到它的密码加密工具） -->\n<dependency>\n    <groupId>org.springframework.security</groupId>\n    <artifactId>spring-security-crypto</artifactId>\n</dependency>\n\n// service/AuthService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.UserRepository;\nimport java.security.SecureRandom;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.HexFormat;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class AuthService {\n\n    public static final Duration SESSION_TTL = Duration.ofDays(7);\n    private static final String USERNAME = "[A-Za-z0-9_]{3,20}";\n\n    public static class AuthException extends RuntimeException {\n        public final int status;\n\n        public AuthException(int status, String message) {\n            super(message);\n            this.status = status;\n        }\n    }\n\n    public record Login(String token, User user) {}\n\n    private final UserRepository users;\n    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder();\n    private final SecureRandom random = new SecureRandom();\n\n    public AuthService(UserRepository users) {\n        this.users = users;\n    }\n\n    public User register(String username, String password) {\n        // TODO 1：用户名为 null 或不匹配 USERNAME（username.matches）、密码为 null 或少于 8 位时，\n        //         抛出 new AuthException(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n        // TODO 2：用 encoder.encode(password) 算出哈希，调用 users.create；\n        //         捕获 UserRepository.UsernameTakenException，改为抛出 AuthException(409, "用户名已被注册")\n        return null;\n    }\n\n    public Login login(String username, String password) {\n        // TODO 3：找用户；不存在或 encoder.matches(密码, 哈希) 不通过时抛出 AuthException(401, "用户名或密码错误")\n        // TODO 4：生成 32 个随机字节（random.nextBytes），用 HexFormat.of().formatHex 转成令牌；\n        //         保存会话（过期时间 Instant.now().plus(SESSION_TTL)），返回 new Login(令牌, 用户)\n        return null;\n    }\n\n    public User currentUser(String token) {\n        // TODO 5：令牌为空或 users.findBySession 找不到时抛出 AuthException(401, "请先登录")\n        return null;\n    }\n\n    public void logout(String token) {\n        if (token != null) {\n            users.deleteSession(token);\n        }\n    }\n}',explain:[{at:'<!-- pom.xml 的 <dependencies> 里加上（只用到它的密码加密工具） -->',to:'</dependency>',text:'spring-security-crypto 是 Spring Security 里单独的加密工具包，有现成的 bcrypt 实现。这里不引入完整的 Spring Security，否则它会默认给所有接口加上登录保护。改完点 Load Maven Changes。'},{at:'// service/AuthService.java',to:'import org.springframework.stereotype.Service;',text:'新建 service 包。SecureRandom 是密码学安全的随机数生成器，千万不要用 Random；HexFormat 把字节转成十六进制文本。'},{at:'@Service',to:'public class AuthService {',text:'@Service 和 @Repository 一样，让 Spring 创建并管理这个对象，只是名字表明它是业务逻辑层。'},{at:'public static final Duration SESSION_TTL = Duration.ofDays(7);',to:'private static final String USERNAME = "[A-Za-z0-9_]{3,20}";',text:'会话有效期 7 天；用户名规则的正则表达式：字母、数字、下划线，3 到 20 个。'},{at:'public static class AuthException extends RuntimeException {',to:'this.status = status;',text:'业务错误带上对应的状态码，GlobalErrors 里统一把它变成响应。'},{at:'public record Login(String token, User user) {}',text:'登录的结果：令牌和用户，用一个 record 一起返回。'},{at:'private final UserRepository users;',to:'this.users = users;',text:'依赖用户仓库；bcrypt 编码器和随机数生成器直接创建。'},{at:'public User register(',to:'return null;',text:'注册，要你补全。'},{at:'public Login login(',to:'return null;',text:'登录，要你补全。'},{at:'public User currentUser(',to:'return null;',text:'查当前用户，要你补全。'},{at:'public void logout(String token) {',to:'users.deleteSession(token);',text:'退出：有令牌就删掉这个会话。'}],solution:{code:'<!-- pom.xml 的 <dependencies> 里加上（只用到它的密码加密工具） -->\n<dependency>\n    <groupId>org.springframework.security</groupId>\n    <artifactId>spring-security-crypto</artifactId>\n</dependency>\n\n// service/AuthService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.UserRepository;\nimport java.security.SecureRandom;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.HexFormat;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class AuthService {\n\n    public static final Duration SESSION_TTL = Duration.ofDays(7);\n    private static final String USERNAME = "[A-Za-z0-9_]{3,20}";\n\n    public static class AuthException extends RuntimeException {\n        public final int status;\n\n        public AuthException(int status, String message) {\n            super(message);\n            this.status = status;\n        }\n    }\n\n    public record Login(String token, User user) {}\n\n    private final UserRepository users;\n    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder();\n    private final SecureRandom random = new SecureRandom();\n\n    public AuthService(UserRepository users) {\n        this.users = users;\n    }\n\n    public User register(String username, String password) {\n        if (username == null || !username.matches(USERNAME) || password == null || password.length() < 8) {\n            throw new AuthException(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位");\n        }\n        try {\n            return users.create(username, encoder.encode(password));\n        } catch (UserRepository.UsernameTakenException e) {\n            throw new AuthException(409, "用户名已被注册");\n        }\n    }\n\n    public Login login(String username, String password) {\n        User user = username == null ? null : users.findByUsername(username).orElse(null);\n        if (user == null || password == null || !encoder.matches(password, user.passwordHash())) {\n            throw new AuthException(401, "用户名或密码错误");\n        }\n        byte[] bytes = new byte[32];\n        random.nextBytes(bytes);\n        String token = HexFormat.of().formatHex(bytes);\n        users.createSession(token, user.id(), Instant.now().plus(SESSION_TTL));\n        return new Login(token, user);\n    }\n\n    public User currentUser(String token) {\n        if (token == null || token.isEmpty()) {\n            throw new AuthException(401, "请先登录");\n        }\n        return users.findBySession(token).orElseThrow(() -> new AuthException(401, "请先登录"));\n    }\n\n    public void logout(String token) {\n        if (token != null) {\n            users.deleteSession(token);\n        }\n    }\n}',explain:[{at:'<!-- pom.xml 的 <dependencies> 里加上（只用到它的密码加密工具） -->',to:'</dependency>',text:'spring-security-crypto 是 Spring Security 里单独的加密工具包，有现成的 bcrypt 实现。这里不引入完整的 Spring Security，否则它会默认给所有接口加上登录保护。改完点 Load Maven Changes。'},{at:'// service/AuthService.java',to:'import org.springframework.stereotype.Service;',text:'新建 service 包。SecureRandom 是密码学安全的随机数生成器，千万不要用 Random；HexFormat 把字节转成十六进制文本。'},{at:'@Service',to:'public class AuthService {',text:'@Service 和 @Repository 一样，让 Spring 创建并管理这个对象，只是名字表明它是业务逻辑层。'},{at:'public static final Duration SESSION_TTL = Duration.ofDays(7);',to:'private static final String USERNAME = "[A-Za-z0-9_]{3,20}";',text:'会话有效期 7 天；用户名规则的正则表达式：字母、数字、下划线，3 到 20 个。'},{at:'public static class AuthException extends RuntimeException {',to:'this.status = status;',text:'业务错误带上对应的状态码，GlobalErrors 里统一把它变成响应。'},{at:'public record Login(String token, User user) {}',text:'登录的结果：令牌和用户，用一个 record 一起返回。'},{at:'private final UserRepository users;',to:'this.users = users;',text:'依赖用户仓库；bcrypt 编码器和随机数生成器直接创建。'},{at:'public User register(',to:'throw new AuthException(400,',text:'先按规则检查，不合格直接抛出 400，不碰数据库。matches 要求整个字符串都符合正则。'},{at:'try {',to:'throw new AuthException(409, "用户名已被注册");',text:'encode 会自动生成随机盐，结果里同时包含算法、成本、盐和哈希值，存这一个字符串就够了。用户名重复时翻译成 409。'},{at:'public Login login(',to:'throw new AuthException(401, "用户名或密码错误");',text:'用户不存在和密码错误给出同样的提示，不暴露这个用户名是否注册过。matches 从存下的值里取出盐，算一遍再比较。'},{at:'byte[] bytes = new byte[32];',to:'return new Login(token, user);',text:'用安全的随机数生成 64 个十六进制字符的令牌，保存会话，返回令牌和用户。'},{at:'public User currentUser(',to:'return users.findBySession(token).orElseThrow(',text:'没有令牌、令牌无效或过期，都是“请先登录”。orElseThrow 在 Optional 为空时抛出括号里创建的异常。'},{at:'public void logout(String token) {',to:'users.deleteSession(token);',text:'退出：有令牌就删掉这个会话。'}]}},node:{practice:{steps:['新建 src/services 文件夹和 auth.js，按骨架写，补完 TODO。'],expect:'文件保存好即可，下一个任务把它接到路由上'},code:'// src/services/auth.js\nconst crypto = require("node:crypto");\nconst users = require("../db/users");\n\nconst SESSION_TTL = 7 * 24 * 60 * 60 * 1000;\nconst USERNAME = /^[A-Za-z0-9_]{3,20}$/;\n\nclass AuthError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nfunction hashPassword(password) {\n  const salt = crypto.randomBytes(16).toString("hex");\n  const hash = crypto.scryptSync(password, salt, 64).toString("hex");\n  return `${salt}:${hash}`;\n}\n\nfunction verifyPassword(password, stored) {\n  const [salt, hash] = stored.split(":");\n  const actual = crypto.scryptSync(password, salt, 64);\n  return crypto.timingSafeEqual(actual, Buffer.from(hash, "hex"));\n}\n\n// 注册：检查格式，保存哈希后的密码，返回 { id, username }\nfunction register(username, password) {\n  // TODO 1：用户名不是字符串或不符合 USERNAME、密码不是字符串或少于 8 位时，\n  //         抛出 new AuthError(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n  // TODO 2：调用 users.createUser(username, hashPassword(password)) 并返回结果；\n  //         捕获 users.UsernameTakenError，改为抛出 AuthError(409, "用户名已被注册")\n}\n\n// 登录：核对密码，创建会话，返回 { token, user: { id, username } }\nfunction login(username, password) {\n  // TODO 3：找用户；用户不存在或 verifyPassword 不通过时，抛出 AuthError(401, "用户名或密码错误")\n  // TODO 4：用 crypto.randomBytes(32).toString("hex") 生成令牌，保存会话（过期时间 Date.now() + SESSION_TTL）\n}\n\n// 当前用户：令牌为空或找不到时抛出 AuthError(401, "请先登录")\nfunction currentUser(token) {\n  // TODO 5\n}\n\nfunction logout(token) {\n  if (token) users.deleteSession(token);\n}\n\nmodule.exports = { AuthError, SESSION_TTL, register, login, currentUser, logout };',explain:[{at:'// src/services/auth.js',to:'const users = require("../db/users");',text:'业务逻辑层（services）。node:crypto 是 Node.js 自带的加密模块，不用安装。'},{at:'const SESSION_TTL = 7 * 24 * 60 * 60 * 1000;',text:'会话有效期 7 天，单位毫秒。TTL 是 time to live（存活时间）的缩写。'},{at:'const USERNAME = /^[A-Za-z0-9_]{3,20}$/;',text:'用户名规则的正则表达式：^ 和 $ 表示从头到尾都要匹配；[A-Za-z0-9_] 是字母、数字、下划线中的一个；{3,20} 表示重复 3 到 20 次。'},{at:'class AuthError extends Error {',to:'this.status = status;',text:'业务错误带上对应的状态码，路由层直接用它返回。super(message) 调用父类 Error 的构造函数，设置错误信息。'},{at:'function hashPassword(password) {',to:'return `${salt}:${hash}`;',text:'慢哈希：scrypt 是 Node.js 自带的密码哈希算法。每个密码生成 16 字节的随机盐，算出 64 字节的哈希，存成“盐:哈希”一个字符串。scryptSync 是同步版本，算一次要几十毫秒，这期间不能处理别的请求，访问量大时应该换成异步的 crypto.scrypt。'},{at:'function verifyPassword(password, stored) {',to:'return crypto.timingSafeEqual(actual, Buffer.from(hash, "hex"));',text:'核对密码：从存下的值里取出盐，用同样的方法算一遍再比较。timingSafeEqual 比较的耗时和内容无关，防止坏人通过“比较用了多久”一点点猜出哈希值。'},{at:'function register(',text:'注册，要你补全。'},{at:'function login(',text:'登录，要你补全。'},{at:'function currentUser(',text:'查当前用户，要你补全。'},{at:'function logout(',to:'if (token) users.deleteSession(token);',text:'退出：有令牌就删掉这个会话。'},{at:'module.exports = {',text:'导出错误类型、有效期和四个功能。'}],solution:{code:'// src/services/auth.js\nconst crypto = require("node:crypto");\nconst users = require("../db/users");\n\nconst SESSION_TTL = 7 * 24 * 60 * 60 * 1000;\nconst USERNAME = /^[A-Za-z0-9_]{3,20}$/;\n\nclass AuthError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nfunction hashPassword(password) {\n  const salt = crypto.randomBytes(16).toString("hex");\n  const hash = crypto.scryptSync(password, salt, 64).toString("hex");\n  return `${salt}:${hash}`;\n}\n\nfunction verifyPassword(password, stored) {\n  const [salt, hash] = stored.split(":");\n  const actual = crypto.scryptSync(password, salt, 64);\n  return crypto.timingSafeEqual(actual, Buffer.from(hash, "hex"));\n}\n\nfunction register(username, password) {\n  if (typeof username !== "string" || !USERNAME.test(username) || typeof password !== "string" || password.length < 8) {\n    throw new AuthError(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位");\n  }\n  try {\n    return users.createUser(username, hashPassword(password));\n  } catch (err) {\n    if (err instanceof users.UsernameTakenError) throw new AuthError(409, "用户名已被注册");\n    throw err;\n  }\n}\n\nfunction login(username, password) {\n  const user = typeof username === "string" ? users.findUserByName(username) : undefined;\n  if (!user || typeof password !== "string" || !verifyPassword(password, user.password_hash)) {\n    throw new AuthError(401, "用户名或密码错误");\n  }\n  const token = crypto.randomBytes(32).toString("hex");\n  users.createSession(token, user.id, Date.now() + SESSION_TTL);\n  return { token, user: { id: user.id, username: user.username } };\n}\n\nfunction currentUser(token) {\n  const user = token ? users.findUserBySession(token) : undefined;\n  if (!user) throw new AuthError(401, "请先登录");\n  return user;\n}\n\nfunction logout(token) {\n  if (token) users.deleteSession(token);\n}\n\nmodule.exports = { AuthError, SESSION_TTL, register, login, currentUser, logout };',explain:[{at:'// src/services/auth.js',to:'const users = require("../db/users");',text:'业务逻辑层（services）。node:crypto 是 Node.js 自带的加密模块，不用安装。'},{at:'const SESSION_TTL = 7 * 24 * 60 * 60 * 1000;',text:'会话有效期 7 天，单位毫秒。TTL 是 time to live（存活时间）的缩写。'},{at:'const USERNAME = /^[A-Za-z0-9_]{3,20}$/;',text:'用户名规则的正则表达式：^ 和 $ 表示从头到尾都要匹配；[A-Za-z0-9_] 是字母、数字、下划线中的一个；{3,20} 表示重复 3 到 20 次。'},{at:'class AuthError extends Error {',to:'this.status = status;',text:'业务错误带上对应的状态码，路由层直接用它返回。super(message) 调用父类 Error 的构造函数，设置错误信息。'},{at:'function hashPassword(password) {',to:'return `${salt}:${hash}`;',text:'慢哈希：scrypt 是 Node.js 自带的密码哈希算法。每个密码生成 16 字节的随机盐，算出 64 字节的哈希，存成“盐:哈希”一个字符串。scryptSync 是同步版本，算一次要几十毫秒，这期间不能处理别的请求，访问量大时应该换成异步的 crypto.scrypt。'},{at:'function verifyPassword(password, stored) {',to:'return crypto.timingSafeEqual(actual, Buffer.from(hash, "hex"));',text:'核对密码：从存下的值里取出盐，用同样的方法算一遍再比较。timingSafeEqual 比较的耗时和内容无关，防止坏人通过“比较用了多久”一点点猜出哈希值。'},{at:'function register(',to:'throw new AuthError(400,',text:'先按规则检查，不合格直接抛出 400，不碰数据库。typeof 检查是防止请求里传的不是字符串（比如数字或者没传）。'},{at:'try {',to:'throw err;',text:'保存哈希后的密码。用户名重复时把数据层的错误翻译成 409。'},{at:'function login(',to:'throw new AuthError(401, "用户名或密码错误");',text:'用户不存在和密码错误给出同样的提示，不暴露这个用户名是否注册过。'},{at:'const token = crypto.randomBytes(32).toString("hex");',to:'return { token, user: { id: user.id, username: user.username } };',text:'用密码学安全的随机数生成令牌，保存会话，返回令牌和用户（不带密码哈希）。'},{at:'function currentUser(token) {',to:'return user;',text:'没有令牌、令牌无效或过期，都是“请先登录”。'},{at:'function logout(',to:'if (token) users.deleteSession(token);',text:'退出：删掉这个会话。'},{at:'module.exports = {',text:'导出。'}]}},python:{practice:{steps:['新建 app/services 文件夹，在里面放一个空的 __init__.py，再新建 auth.py，按骨架写，补完 TODO。'],expect:'文件保存好即可，下一个任务把它接到路由上'},code:'# app/services/auth.py\nimport hashlib\nimport hmac\nimport re\nimport secrets\nimport time\n\nfrom app import users\n\nSESSION_TTL = 7 * 24 * 60 * 60\nUSERNAME = re.compile(r"[A-Za-z0-9_]{3,20}")\n\n\nclass AuthError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef hash_password(password):\n    salt = secrets.token_bytes(16)\n    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)\n    return f"{salt.hex()}:{digest.hex()}"\n\n\ndef verify_password(password, stored):\n    salt, digest = stored.split(":")\n    actual = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt), n=2**14, r=8, p=1)\n    return hmac.compare_digest(actual.hex(), digest)\n\n\ndef register(username, password):\n    """检查格式，保存哈希后的密码，返回 {"id", "username"}"""\n    # TODO 1：用户名不完全符合 USERNAME（用 fullmatch）或密码少于 8 位时，\n    #         抛出 AuthError(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n    # TODO 2：调用 users.create_user(username, hash_password(password)) 并返回；\n    #         捕获 users.UsernameTaken，改为抛出 AuthError(409, "用户名已被注册")\n    pass\n\n\ndef login(username, password):\n    """核对密码，创建会话，返回 (令牌, {"id", "username"})"""\n    # TODO 3：找用户；不存在或 verify_password 不通过时抛出 AuthError(401, "用户名或密码错误")\n    # TODO 4：用 secrets.token_hex(32) 生成令牌，保存会话（过期时间 int(time.time()) + SESSION_TTL）\n    pass\n\n\ndef current_user(token):\n    """令牌为空或找不到时抛出 AuthError(401, "请先登录")"""\n    # TODO 5\n    pass\n\n\ndef logout(token):\n    if token:\n        users.delete_session(token)',explain:[{at:'# app/services/auth.py',to:'from app import users',text:'业务逻辑层（services）。hashlib、hmac、re、secrets 都是 Python 自带的模块：secrets 生成密码学安全的随机数，千万不要用 random。'},{at:'SESSION_TTL = 7 * 24 * 60 * 60',text:'会话有效期 7 天，单位秒。TTL 是 time to live（存活时间）的缩写。'},{at:'USERNAME = re.compile(r"[A-Za-z0-9_]{3,20}")',text:'用户名规则的正则表达式：[A-Za-z0-9_] 是字母、数字、下划线中的一个，{3,20} 表示重复 3 到 20 次。r"" 是原始字符串，里面的反斜杠不会被转义。'},{at:'class AuthError(Exception):',to:'self.message = message',text:'业务错误带上对应的状态码，main.py 里统一把它变成响应。'},{at:'def hash_password(password):',to:'return f"{salt.hex()}:{digest.hex()}"',text:'慢哈希：scrypt 是专门为密码设计的算法，n、r、p 决定它有多“慢”、要用多少内存。每个密码生成 16 字节的随机盐，存成“盐:哈希”一个字符串（都转成十六进制文本）。'},{at:'def verify_password(password, stored):',to:'return hmac.compare_digest(actual.hex(), digest)',text:'核对密码：取出盐，用同样的参数再算一遍再比较。compare_digest 比较的耗时和内容无关，防止坏人通过“比较用了多久”一点点猜出哈希值。'},{at:'def register(username, password):',to:'    pass',text:'注册，要你补全。'},{at:'def login(username, password):',to:'    pass',text:'登录，要你补全。'},{at:'def current_user(token):',to:'    pass',text:'查当前用户，要你补全。'},{at:'def logout(token):',to:'users.delete_session(token)',text:'退出：有令牌就删掉这个会话。'}],solution:{code:'# app/services/auth.py\nimport hashlib\nimport hmac\nimport re\nimport secrets\nimport time\n\nfrom app import users\n\nSESSION_TTL = 7 * 24 * 60 * 60\nUSERNAME = re.compile(r"[A-Za-z0-9_]{3,20}")\n\n\nclass AuthError(Exception):\n    def __init__(self, status, message):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\ndef hash_password(password):\n    salt = secrets.token_bytes(16)\n    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)\n    return f"{salt.hex()}:{digest.hex()}"\n\n\ndef verify_password(password, stored):\n    salt, digest = stored.split(":")\n    actual = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt), n=2**14, r=8, p=1)\n    return hmac.compare_digest(actual.hex(), digest)\n\n\ndef register(username, password):\n    if not USERNAME.fullmatch(username) or len(password) < 8:\n        raise AuthError(400, "用户名要 3–20 个字母、数字或下划线，密码至少 8 位")\n    try:\n        return users.create_user(username, hash_password(password))\n    except users.UsernameTaken:\n        raise AuthError(409, "用户名已被注册") from None\n\n\ndef login(username, password):\n    user = users.find_user_by_name(username)\n    if user is None or not verify_password(password, user["password_hash"]):\n        raise AuthError(401, "用户名或密码错误")\n    token = secrets.token_hex(32)\n    users.create_session(token, user["id"], int(time.time()) + SESSION_TTL)\n    return token, {"id": user["id"], "username": user["username"]}\n\n\ndef current_user(token):\n    user = users.find_user_by_session(token) if token else None\n    if user is None:\n        raise AuthError(401, "请先登录")\n    return user\n\n\ndef logout(token):\n    if token:\n        users.delete_session(token)',explain:[{at:'# app/services/auth.py',to:'from app import users',text:'业务逻辑层（services）。hashlib、hmac、re、secrets 都是 Python 自带的模块：secrets 生成密码学安全的随机数，千万不要用 random。'},{at:'SESSION_TTL = 7 * 24 * 60 * 60',text:'会话有效期 7 天，单位秒。TTL 是 time to live（存活时间）的缩写。'},{at:'USERNAME = re.compile(r"[A-Za-z0-9_]{3,20}")',text:'用户名规则的正则表达式：[A-Za-z0-9_] 是字母、数字、下划线中的一个，{3,20} 表示重复 3 到 20 次。r"" 是原始字符串，里面的反斜杠不会被转义。'},{at:'class AuthError(Exception):',to:'self.message = message',text:'业务错误带上对应的状态码，main.py 里统一把它变成响应。'},{at:'def hash_password(password):',to:'return f"{salt.hex()}:{digest.hex()}"',text:'慢哈希：scrypt 是专门为密码设计的算法，n、r、p 决定它有多“慢”、要用多少内存。每个密码生成 16 字节的随机盐，存成“盐:哈希”一个字符串（都转成十六进制文本）。'},{at:'def verify_password(password, stored):',to:'return hmac.compare_digest(actual.hex(), digest)',text:'核对密码：取出盐，用同样的参数再算一遍再比较。compare_digest 比较的耗时和内容无关，防止坏人通过“比较用了多久”一点点猜出哈希值。'},{at:'def register(username, password):',to:'raise AuthError(400,',text:'先按规则检查，不合格直接抛出 400，不碰数据库。fullmatch 要求整个字符串都符合规则。'},{at:'try:',to:'raise AuthError(409, "用户名已被注册") from None',text:'保存哈希后的密码。用户名重复时把数据层的异常翻译成 409。'},{at:'def login(username, password):',to:'raise AuthError(401, "用户名或密码错误")',text:'用户不存在和密码错误给出同样的提示，不暴露这个用户名是否注册过。'},{at:'token = secrets.token_hex(32)',to:'return token, {"id": user["id"], "username": user["username"]}',text:'生成 64 个十六进制字符的令牌，保存会话，返回令牌和用户（不带密码哈希）。'},{at:'def current_user(token):',to:'return user',text:'没有令牌、令牌无效或过期，都是“请先登录”。'},{at:'def logout(token):',to:'users.delete_session(token)',text:'退出：有令牌就删掉这个会话。'}]}}}},
  {title:'任务三：账号接口',body:'最后写处理请求的层：读取 JSON 正文、读写 Cookie、调用业务逻辑层、把错误翻译成 400、401、409。',variants:{go:{practice:{steps:['新建 internal/handler/auth.go，按骨架写，补完 TODO。','按最后的注释修改 store.go、handler.go 和 main.go。模板渲染的同学 New 的最后一个参数还是模板。','go run . 启动，用 curl 试一试（PowerShell 里写 curl.exe）：curl -i -X POST localhost:8080/api/register -H "Content-Type: application/json" -d "{\\"username\\":\\"tom\\",\\"password\\":\\"12345678\\"}"'],expect:'HTTP/1.1 201 Created\nContent-Type: application/json\nX-Request-Id: req-1\n\n{"id":1,"username":"tom"}'},code:'// internal/handler/auth.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\nconst sessionCookie = "session"\n\ntype credentials struct {\n    Username string `json:"username"`\n    Password string `json:"password"`\n}\n\nfunc setSession(w http.ResponseWriter, token string) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: token, Path: "/",\n        MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode})\n}\n\nfunc clearSession(w http.ResponseWriter) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/",\n        MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode})\n}\n\nfunc sessionToken(r *http.Request) string {\n    c, err := r.Cookie(sessionCookie)\n    if err != nil {\n        return ""\n    }\n    return c.Value\n}\n\n// authError 把业务逻辑层的错误翻译成状态码。\nfunc (h *Handler) authError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrInvalidInput):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    case errors.Is(err, store.ErrUsernameTaken):\n        writeJSON(w, http.StatusConflict, map[string]string{"error": "用户名已被注册"})\n    case errors.Is(err, service.ErrBadCredentials), errors.Is(err, service.ErrNotLoggedIn):\n        writeJSON(w, http.StatusUnauthorized, map[string]string{"error": err.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc readCredentials(w http.ResponseWriter, r *http.Request) (credentials, bool) {\n    var c credentials\n    if err := json.NewDecoder(r.Body).Decode(&c); err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求正文要是 JSON"})\n        return c, false\n    }\n    return c, true\n}\n\nfunc (h *Handler) register(w http.ResponseWriter, r *http.Request) {\n    // TODO 1：readCredentials 读出用户名密码；调用 h.auth.Register，出错交给 h.authError；成功返回 201 和用户\n}\n\nfunc (h *Handler) login(w http.ResponseWriter, r *http.Request) {\n    // TODO 2：读出用户名密码，调用 h.auth.Login；出错交给 h.authError；成功时 setSession(w, 令牌)，返回 200 和用户\n}\n\nfunc (h *Handler) me(w http.ResponseWriter, r *http.Request) {\n    // TODO 3：用 h.auth.CurrentUser(sessionToken(r)) 找当前用户，出错交给 h.authError，成功返回用户\n}\n\nfunc (h *Handler) logout(w http.ResponseWriter, r *http.Request) {\n    // TODO 4：调用 h.auth.Logout(sessionToken(r))，出错返回 500；然后 clearSession(w)，返回 204（w.WriteHeader）\n}\n\n// 另外三处小改动：\n// internal/store/store.go：给 QuestionStore 加一个方法，让别的仓库能共用数据库连接\n//     func (s *QuestionStore) DB() *sql.DB { return s.db }\n// internal/handler/handler.go：Handler 结构体加上字段 auth *service.AuthService，\n//     New 多一个参数 auth（放在第二个），import 里加上 "zixishi/internal/service"；Routes 里加上：\n//     mux.HandleFunc("POST /api/register", h.register)\n//     mux.HandleFunc("POST /api/login", h.login)\n//     mux.HandleFunc("GET /api/me", h.me)\n//     mux.HandleFunc("POST /api/logout", h.logout)\n// main.go：导入数据之后、创建 Handler 之前加上下面几行，再把 auth 传给 handler.New\nus, err := store.NewUserStore(qs.DB())\nif err != nil {\n    log.Fatalf("创建用户表失败：%v", err)\n}\nauth := service.NewAuthService(us)',explain:[{at:'// internal/handler/auth.go',to:'"zixishi/internal/store"',text:'账号相关的接口单独放一个文件，还是 handler 包。'},{at:'const sessionCookie = "session"',text:'Cookie 的名字。'},{at:'type credentials struct {',to:'Password string `json:"password"`',text:'注册和登录时请求正文的格式：{"username": …, "password": …}。'},{at:'func setSession(',to:'MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode})',text:'设置会话 Cookie：有效期和服务器上的会话一样是 7 天，加上 HttpOnly 和 SameSite=Lax。'},{at:'func clearSession(',to:'MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode})',text:'让浏览器删掉 Cookie：Go 里 MaxAge 写负数，会发出 Max-Age=0。'},{at:'func sessionToken(r *http.Request) string {',to:'return c.Value',text:'从请求里读出会话令牌，没有这个 Cookie 时返回空字符串。'},{at:'func (h *Handler) authError(',to:'h.serverError(w, err)',text:'switch 不写条件时，从上到下找第一个成立的 case：参数不合格 400，用户名已存在 409，密码错误或没登录 401，其他都是 500。'},{at:'func readCredentials(',to:'return c, true',text:'把请求正文解析成 credentials；不是合法的 JSON 时直接返回 400，第二个返回值告诉调用方要不要继续。'},{at:'func (h *Handler) register(',text:'注册接口，要你补全。'},{at:'func (h *Handler) login(',text:'登录接口，要你补全。'},{at:'func (h *Handler) me(',text:'当前用户接口，要你补全。'},{at:'func (h *Handler) logout(',text:'退出接口，要你补全。'},{at:'us, err := store.NewUserStore(qs.DB())',to:'auth := service.NewAuthService(us)',text:'入口把三层组装起来：数据库连接 → 用户仓库 → 账号服务 → Handler。每一层只认识自己下面那一层。'}],solution:{code:'// internal/handler/auth.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\nconst sessionCookie = "session"\n\ntype credentials struct {\n    Username string `json:"username"`\n    Password string `json:"password"`\n}\n\nfunc setSession(w http.ResponseWriter, token string) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: token, Path: "/",\n        MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode})\n}\n\nfunc clearSession(w http.ResponseWriter) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/",\n        MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode})\n}\n\nfunc sessionToken(r *http.Request) string {\n    c, err := r.Cookie(sessionCookie)\n    if err != nil {\n        return ""\n    }\n    return c.Value\n}\n\n// authError 把业务逻辑层的错误翻译成状态码。\nfunc (h *Handler) authError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrInvalidInput):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    case errors.Is(err, store.ErrUsernameTaken):\n        writeJSON(w, http.StatusConflict, map[string]string{"error": "用户名已被注册"})\n    case errors.Is(err, service.ErrBadCredentials), errors.Is(err, service.ErrNotLoggedIn):\n        writeJSON(w, http.StatusUnauthorized, map[string]string{"error": err.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc readCredentials(w http.ResponseWriter, r *http.Request) (credentials, bool) {\n    var c credentials\n    if err := json.NewDecoder(r.Body).Decode(&c); err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求正文要是 JSON"})\n        return c, false\n    }\n    return c, true\n}\n\nfunc (h *Handler) register(w http.ResponseWriter, r *http.Request) {\n    c, ok := readCredentials(w, r)\n    if !ok {\n        return\n    }\n    u, err := h.auth.Register(c.Username, c.Password)\n    if err != nil {\n        h.authError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusCreated, u)\n}\n\nfunc (h *Handler) login(w http.ResponseWriter, r *http.Request) {\n    c, ok := readCredentials(w, r)\n    if !ok {\n        return\n    }\n    token, u, err := h.auth.Login(c.Username, c.Password)\n    if err != nil {\n        h.authError(w, err)\n        return\n    }\n    setSession(w, token)\n    writeJSON(w, http.StatusOK, u)\n}\n\nfunc (h *Handler) me(w http.ResponseWriter, r *http.Request) {\n    u, err := h.auth.CurrentUser(sessionToken(r))\n    if err != nil {\n        h.authError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, u)\n}\n\nfunc (h *Handler) logout(w http.ResponseWriter, r *http.Request) {\n    if err := h.auth.Logout(sessionToken(r)); err != nil {\n        h.serverError(w, err)\n        return\n    }\n    clearSession(w)\n    w.WriteHeader(http.StatusNoContent)\n}\n\n// 另外三处小改动：\n// internal/store/store.go：给 QuestionStore 加一个方法，让别的仓库能共用数据库连接\n//     func (s *QuestionStore) DB() *sql.DB { return s.db }\n// internal/handler/handler.go：Handler 结构体加上字段 auth *service.AuthService，\n//     New 多一个参数 auth（放在第二个），import 里加上 "zixishi/internal/service"；Routes 里加上：\n//     mux.HandleFunc("POST /api/register", h.register)\n//     mux.HandleFunc("POST /api/login", h.login)\n//     mux.HandleFunc("GET /api/me", h.me)\n//     mux.HandleFunc("POST /api/logout", h.logout)\n// main.go：导入数据之后、创建 Handler 之前加上下面几行，再把 auth 传给 handler.New\nus, err := store.NewUserStore(qs.DB())\nif err != nil {\n    log.Fatalf("创建用户表失败：%v", err)\n}\nauth := service.NewAuthService(us)',explain:[{at:'// internal/handler/auth.go',to:'"zixishi/internal/store"',text:'账号相关的接口单独放一个文件，还是 handler 包。'},{at:'const sessionCookie = "session"',text:'Cookie 的名字。'},{at:'type credentials struct {',to:'Password string `json:"password"`',text:'注册和登录时请求正文的格式：{"username": …, "password": …}。'},{at:'func setSession(',to:'MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode})',text:'设置会话 Cookie：有效期和服务器上的会话一样是 7 天，加上 HttpOnly 和 SameSite=Lax。'},{at:'func clearSession(',to:'MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode})',text:'让浏览器删掉 Cookie：Go 里 MaxAge 写负数，会发出 Max-Age=0。'},{at:'func sessionToken(r *http.Request) string {',to:'return c.Value',text:'从请求里读出会话令牌，没有这个 Cookie 时返回空字符串。'},{at:'func (h *Handler) authError(',to:'h.serverError(w, err)',text:'switch 不写条件时，从上到下找第一个成立的 case：参数不合格 400，用户名已存在 409，密码错误或没登录 401，其他都是 500。'},{at:'func readCredentials(',to:'return c, true',text:'把请求正文解析成 credentials；不是合法的 JSON 时直接返回 400，第二个返回值告诉调用方要不要继续。'},{at:'func (h *Handler) register(',to:'return',text:'读出用户名密码，格式不对时 readCredentials 已经返回了 400。'},{at:'u, err := h.auth.Register(c.Username, c.Password)',to:'writeJSON(w, http.StatusCreated, u)',text:'交给业务逻辑层注册。成功返回 201，User 的 PasswordHash 字段带 json:"-"，不会出现在 JSON 里。'},{at:'func (h *Handler) login(',to:'return',text:'读出用户名密码。'},{at:'token, u, err := h.auth.Login(c.Username, c.Password)',to:'writeJSON(w, http.StatusOK, u)',text:'登录成功后，先设置 Cookie（它是响应头），再写正文。'},{at:'func (h *Handler) me(',to:'writeJSON(w, http.StatusOK, u)',text:'按 Cookie 里的令牌找当前用户，没登录时 authError 返回 401。'},{at:'func (h *Handler) logout(',to:'w.WriteHeader(http.StatusNoContent)',text:'先删掉服务器上的会话，再让浏览器删掉 Cookie，返回 204（没有正文）。'},{at:'us, err := store.NewUserStore(qs.DB())',to:'auth := service.NewAuthService(us)',text:'入口把三层组装起来：数据库连接 → 用户仓库 → 账号服务 → Handler。每一层只认识自己下面那一层。'}]}},java:{practice:{steps:['新建 controller/AuthController.java，按骨架写，补完 TODO。','按最后一部分修改 GlobalErrors.java。','重启服务，用 curl 试一试（PowerShell 里写 curl.exe）：curl -i -X POST localhost:8080/api/register -H "Content-Type: application/json" -d "{\\"username\\":\\"tom\\",\\"password\\":\\"12345678\\"}"'],expect:'HTTP/1.1 201\nX-Request-Id: req-1\nContent-Type: application/json\n\n{"id":1,"username":"tom"}'},code:'// controller/AuthController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AuthService;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api")\npublic class AuthController {\n\n    public record Credentials(String username, String password) {}\n\n    private final AuthService auth;\n\n    public AuthController(AuthService auth) {\n        this.auth = auth;\n    }\n\n    private static ResponseCookie sessionCookie(String value, long maxAgeSeconds) {\n        return ResponseCookie.from("session", value)\n            .httpOnly(true).sameSite("Lax").path("/").maxAge(maxAgeSeconds).build();\n    }\n\n    @PostMapping("/register")\n    public ResponseEntity<User> register(@RequestBody Credentials body) {\n        // TODO 1：调用 auth.register，返回 201 和用户（ResponseEntity.status(201).body(...)）\n        return null;\n    }\n\n    @PostMapping("/login")\n    public ResponseEntity<User> login(@RequestBody Credentials body) {\n        // TODO 2：调用 auth.login；用 sessionCookie(令牌, AuthService.SESSION_TTL.toSeconds()) 生成 Cookie，\n        //         放进响应头 HttpHeaders.SET_COOKIE（值是 cookie.toString()），正文是用户\n        return null;\n    }\n\n    @GetMapping("/me")\n    public User me(@CookieValue(name = "session", required = false) String token) {\n        // TODO 3：调用 auth.currentUser(token) 并返回\n        return null;\n    }\n\n    @PostMapping("/logout")\n    public ResponseEntity<Void> logout(@CookieValue(name = "session", required = false) String token) {\n        // TODO 4：调用 auth.logout；返回 204（ResponseEntity.noContent()），响应头里放 sessionCookie("", 0)\n        return null;\n    }\n}\n\n// config/GlobalErrors.java：新增一个方法，放在处理 Exception 的方法前面\n@ExceptionHandler(AuthService.AuthException.class)\npublic ResponseEntity<Map<String, String>> auth(AuthService.AuthException e) {\n    return ResponseEntity.status(e.status).body(Map.of("error", e.getMessage()));\n}\n\n@ExceptionHandler(HttpMessageNotReadableException.class)\npublic ResponseEntity<Map<String, String>> badBody() {\n    return ResponseEntity.badRequest().body(Map.of("error", "请求正文要是 JSON"));\n}',explain:[{at:'// controller/AuthController.java',to:'import org.springframework.web.bind.annotation.*;',text:'账号接口的控制器。ResponseCookie 用来生成 Set-Cookie 响应头。'},{at:'@RestController',to:'public class AuthController {',text:'路径前缀 /api。'},{at:'public record Credentials(String username, String password) {}',text:'请求正文的格式。参数写成 @RequestBody Credentials body，Spring 会把 JSON 正文转成这个 record；缺的字段是 null，业务逻辑层会检查。'},{at:'private final AuthService auth;',to:'this.auth = auth;',text:'注入业务逻辑层。'},{at:'private static ResponseCookie sessionCookie(',to:'.httpOnly(true).sameSite("Lax").path("/").maxAge(maxAgeSeconds).build();',text:'生成会话 Cookie：HttpOnly、SameSite=Lax、整个网站有效，有效期单位是秒。退出时用同样的选项、有效期 0，让浏览器删掉它。'},{at:'@PostMapping("/register")',to:'return null;',text:'注册接口，要你补全。'},{at:'@PostMapping("/login")',to:'return null;',text:'登录接口，要你补全。'},{at:'@GetMapping("/me")',to:'return null;',text:'当前用户接口，要你补全。@CookieValue 读取名叫 session 的 Cookie，required = false 表示没有时传 null，而不是报错。'},{at:'@PostMapping("/logout")',to:'return null;',text:'退出接口，要你补全。'},{at:'// config/GlobalErrors.java',text:'全局错误处理再加两种（需要导入 AuthService 和 org.springframework.http.converter.HttpMessageNotReadableException）。'},{at:'@ExceptionHandler(AuthService.AuthException.class)',to:'return ResponseEntity.status(e.status).body(Map.of("error", e.getMessage()));',text:'任何地方抛出 AuthException，都按它带的状态码返回 {"error": …}。控制器里就不用写 try/catch 了。'},{at:'@ExceptionHandler(HttpMessageNotReadableException.class)',to:'return ResponseEntity.badRequest().body(Map.of("error", "请求正文要是 JSON"));',text:'请求正文不是合法的 JSON 时，Spring 抛出这个异常，返回 400，而不是被当成程序出错。'}],solution:{code:'// controller/AuthController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AuthService;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api")\npublic class AuthController {\n\n    public record Credentials(String username, String password) {}\n\n    private final AuthService auth;\n\n    public AuthController(AuthService auth) {\n        this.auth = auth;\n    }\n\n    private static ResponseCookie sessionCookie(String value, long maxAgeSeconds) {\n        return ResponseCookie.from("session", value)\n            .httpOnly(true).sameSite("Lax").path("/").maxAge(maxAgeSeconds).build();\n    }\n\n    @PostMapping("/register")\n    public ResponseEntity<User> register(@RequestBody Credentials body) {\n        return ResponseEntity.status(201).body(auth.register(body.username(), body.password()));\n    }\n\n    @PostMapping("/login")\n    public ResponseEntity<User> login(@RequestBody Credentials body) {\n        AuthService.Login result = auth.login(body.username(), body.password());\n        ResponseCookie cookie = sessionCookie(result.token(), AuthService.SESSION_TTL.toSeconds());\n        return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE, cookie.toString()).body(result.user());\n    }\n\n    @GetMapping("/me")\n    public User me(@CookieValue(name = "session", required = false) String token) {\n        return auth.currentUser(token);\n    }\n\n    @PostMapping("/logout")\n    public ResponseEntity<Void> logout(@CookieValue(name = "session", required = false) String token) {\n        auth.logout(token);\n        return ResponseEntity.noContent().header(HttpHeaders.SET_COOKIE, sessionCookie("", 0).toString()).build();\n    }\n}\n\n// config/GlobalErrors.java：新增一个方法，放在处理 Exception 的方法前面\n@ExceptionHandler(AuthService.AuthException.class)\npublic ResponseEntity<Map<String, String>> auth(AuthService.AuthException e) {\n    return ResponseEntity.status(e.status).body(Map.of("error", e.getMessage()));\n}\n\n@ExceptionHandler(HttpMessageNotReadableException.class)\npublic ResponseEntity<Map<String, String>> badBody() {\n    return ResponseEntity.badRequest().body(Map.of("error", "请求正文要是 JSON"));\n}',explain:[{at:'// controller/AuthController.java',to:'import org.springframework.web.bind.annotation.*;',text:'账号接口的控制器。ResponseCookie 用来生成 Set-Cookie 响应头。'},{at:'@RestController',to:'public class AuthController {',text:'路径前缀 /api。'},{at:'public record Credentials(String username, String password) {}',text:'请求正文的格式。参数写成 @RequestBody Credentials body，Spring 会把 JSON 正文转成这个 record；缺的字段是 null，业务逻辑层会检查。'},{at:'private final AuthService auth;',to:'this.auth = auth;',text:'注入业务逻辑层。'},{at:'private static ResponseCookie sessionCookie(',to:'.httpOnly(true).sameSite("Lax").path("/").maxAge(maxAgeSeconds).build();',text:'生成会话 Cookie：HttpOnly、SameSite=Lax、整个网站有效，有效期单位是秒。退出时用同样的选项、有效期 0，让浏览器删掉它。'},{at:'@PostMapping("/register")',to:'return ResponseEntity.status(201).body(auth.register(body.username(), body.password()));',text:'交给业务逻辑层注册，成功返回 201 和用户；User 的密码哈希带 @JsonIgnore，不会出现在 JSON 里。'},{at:'@PostMapping("/login")',to:'return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE, cookie.toString()).body(result.user());',text:'登录成功后把 Cookie 放进 Set-Cookie 响应头。'},{at:'@GetMapping("/me")',to:'return auth.currentUser(token);',text:'@CookieValue 读取名叫 session 的 Cookie，没有时是 null。没登录时业务层抛出 401。'},{at:'@PostMapping("/logout")',to:'return ResponseEntity.noContent()',text:'删掉服务器上的会话，再发一个有效期 0 的同名 Cookie 让浏览器删掉它，返回 204。'},{at:'// config/GlobalErrors.java',text:'全局错误处理再加两种（需要导入 AuthService 和 org.springframework.http.converter.HttpMessageNotReadableException）。'},{at:'@ExceptionHandler(AuthService.AuthException.class)',to:'return ResponseEntity.status(e.status).body(Map.of("error", e.getMessage()));',text:'任何地方抛出 AuthException，都按它带的状态码返回 {"error": …}。控制器里就不用写 try/catch 了。'},{at:'@ExceptionHandler(HttpMessageNotReadableException.class)',to:'return ResponseEntity.badRequest().body(Map.of("error", "请求正文要是 JSON"));',text:'请求正文不是合法的 JSON 时，Spring 抛出这个异常，返回 400，而不是被当成程序出错。'}]}},node:{practice:{steps:['新建 src/routes/auth.js，按骨架写，补完 TODO。','运行 npm install cookie-parser，按最后一部分修改 app.js。','重启服务，用 curl 试一试（PowerShell 里写 curl.exe）：curl -i -X POST localhost:8080/api/register -H "Content-Type: application/json" -d "{\\"username\\":\\"tom\\",\\"password\\":\\"12345678\\"}"'],expect:'HTTP/1.1 201 Created\nX-Request-Id: req-1\nContent-Type: application/json; charset=utf-8\n\n{"id":1,"username":"tom"}'},code:'// src/routes/auth.js\nconst express = require("express");\nconst auth = require("../services/auth");\n\nconst router = express.Router();\nconst COOKIE = { httpOnly: true, sameSite: "lax", path: "/" };\n\n// 把业务错误翻译成响应；其他错误交给错误处理中间件\nfunction handle(fn) {\n  return (req, res, next) => {\n    try {\n      fn(req, res);\n    } catch (err) {\n      if (err instanceof auth.AuthError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nrouter.post("/register", handle((req, res) => {\n  // TODO 1：从 req.body 取出 username 和 password，调用 auth.register，返回 201 和结果\n}));\n\nrouter.post("/login", handle((req, res) => {\n  // TODO 2：调用 auth.login；用 res.cookie("session", 令牌, { ...COOKIE, maxAge: auth.SESSION_TTL }) 设置 Cookie，返回用户\n}));\n\nrouter.get("/me", handle((req, res) => {\n  // TODO 3：会话令牌在 req.cookies.session 里，调用 auth.currentUser 并返回结果\n}));\n\nrouter.post("/logout", handle((req, res) => {\n  // TODO 4：调用 auth.logout，用 res.clearCookie("session", COOKIE) 删掉 Cookie，返回 204（res.status(204).end()）\n}));\n\nmodule.exports = router;\n\n// app.js：先运行 npm install cookie-parser；在 app.use(requestId) 后面加上两个中间件，\n// 在 app.use("/api", notFound) 前面挂上账号路由\nconst cookieParser = require("cookie-parser");\nconst authRouter = require("./src/routes/auth");\n\napp.use(express.json());\napp.use(cookieParser());\napp.use("/api", authRouter);',explain:[{at:'// src/routes/auth.js',to:'const auth = require("../services/auth");',text:'账号接口的路由，调用业务逻辑层。'},{at:'const router = express.Router();',to:'const COOKIE = { httpOnly: true, sameSite: "lax", path: "/" };',text:'会话 Cookie 的公共选项：HttpOnly、SameSite=Lax、整个网站有效。'},{at:'function handle(fn) {',to:'next(err);',text:'一个“包装函数”：把路由处理函数包起来，统一处理业务错误。AuthError 按它带的状态码返回 {"error": …}；其他意外错误交给第 4 关写的错误处理中间件，返回 500。每个路由就不用各写一遍 try/catch 了。'},{at:'router.post("/register", handle((req, res) => {',text:'注册接口，要你补全。'},{at:'router.post("/login", handle((req, res) => {',text:'登录接口，要你补全。'},{at:'router.get("/me", handle((req, res) => {',text:'当前用户接口，要你补全。'},{at:'router.post("/logout", handle((req, res) => {',text:'退出接口，要你补全。'},{at:'module.exports = router;',text:'导出路由。'},{at:'const cookieParser = require("cookie-parser");',to:'const authRouter = require("./src/routes/auth");',text:'cookie-parser 解析请求头里的 Cookie，放进 req.cookies 对象。'},{at:'app.use(express.json());',text:'express.json() 解析 JSON 格式的请求正文，放进 req.body。不加它，req.body 是 undefined。'},{at:'app.use(cookieParser());',text:'注册 Cookie 解析中间件。'},{at:'app.use("/api", authRouter);',text:'账号路由挂在 /api 下，四个接口就是 /api/register、/api/login、/api/me、/api/logout。要放在 notFound 前面。'}],solution:{code:'// src/routes/auth.js\nconst express = require("express");\nconst auth = require("../services/auth");\n\nconst router = express.Router();\nconst COOKIE = { httpOnly: true, sameSite: "lax", path: "/" };\n\n// 把业务错误翻译成响应；其他错误交给错误处理中间件\nfunction handle(fn) {\n  return (req, res, next) => {\n    try {\n      fn(req, res);\n    } catch (err) {\n      if (err instanceof auth.AuthError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nrouter.post("/register", handle((req, res) => {\n  const { username, password } = req.body;\n  res.status(201).json(auth.register(username, password));\n}));\n\nrouter.post("/login", handle((req, res) => {\n  const { username, password } = req.body;\n  const { token, user } = auth.login(username, password);\n  res.cookie("session", token, { ...COOKIE, maxAge: auth.SESSION_TTL });\n  res.json(user);\n}));\n\nrouter.get("/me", handle((req, res) => {\n  res.json(auth.currentUser(req.cookies.session));\n}));\n\nrouter.post("/logout", handle((req, res) => {\n  auth.logout(req.cookies.session);\n  res.clearCookie("session", COOKIE);\n  res.status(204).end();\n}));\n\nmodule.exports = router;\n\n// app.js：先运行 npm install cookie-parser；在 app.use(requestId) 后面加上两个中间件，\n// 在 app.use("/api", notFound) 前面挂上账号路由\nconst cookieParser = require("cookie-parser");\nconst authRouter = require("./src/routes/auth");\n\napp.use(express.json());\napp.use(cookieParser());\napp.use("/api", authRouter);',explain:[{at:'// src/routes/auth.js',to:'const auth = require("../services/auth");',text:'账号接口的路由，调用业务逻辑层。'},{at:'const router = express.Router();',to:'const COOKIE = { httpOnly: true, sameSite: "lax", path: "/" };',text:'会话 Cookie 的公共选项：HttpOnly、SameSite=Lax、整个网站有效。'},{at:'function handle(fn) {',to:'next(err);',text:'一个“包装函数”：把路由处理函数包起来，统一处理业务错误。AuthError 按它带的状态码返回 {"error": …}；其他意外错误交给第 4 关写的错误处理中间件，返回 500。每个路由就不用各写一遍 try/catch 了。'},{at:'router.post("/register", handle((req, res) => {',to:'res.status(201).json(auth.register(username, password));',text:'从请求正文里解构出用户名和密码，交给业务逻辑层，成功返回 201。'},{at:'router.post("/login", handle((req, res) => {',to:'res.json(user);',text:'登录成功后设置 Cookie：res.cookie 生成 Set-Cookie 响应头，maxAge 单位是毫秒。'},{at:'router.get("/me", handle((req, res) => {',to:'res.json(auth.currentUser(req.cookies.session));',text:'按 Cookie 里的令牌找当前用户，没登录时业务层抛出 401。'},{at:'router.post("/logout", handle((req, res) => {',to:'res.status(204).end();',text:'删掉服务器上的会话，再让浏览器删掉 Cookie，返回 204（没有正文）。clearCookie 的选项要和设置时一样，浏览器才认得是同一个 Cookie。'},{at:'module.exports = router;',text:'导出路由。'},{at:'const cookieParser = require("cookie-parser");',to:'const authRouter = require("./src/routes/auth");',text:'cookie-parser 解析请求头里的 Cookie，放进 req.cookies 对象。'},{at:'app.use(express.json());',text:'express.json() 解析 JSON 格式的请求正文，放进 req.body。不加它，req.body 是 undefined。'},{at:'app.use(cookieParser());',text:'注册 Cookie 解析中间件。'},{at:'app.use("/api", authRouter);',text:'账号路由挂在 /api 下，四个接口就是 /api/register、/api/login、/api/me、/api/logout。要放在 notFound 前面。'}]}},python:{practice:{steps:['新建 app/routers/auth.py，按骨架写，补完 TODO。','按最后一部分修改 main.py。','重启服务，用 curl 试一试（PowerShell 里写 curl.exe）：curl -i -X POST localhost:8080/api/register -H "Content-Type: application/json" -d "{\\"username\\":\\"tom\\",\\"password\\":\\"12345678\\"}"'],expect:'HTTP/1.1 201 Created\ncontent-type: application/json\nx-request-id: req-1\n\n{"id":1,"username":"tom"}'},code:'# app/routers/auth.py\nfrom fastapi import APIRouter, Request, Response\nfrom pydantic import BaseModel\n\nfrom app.services import auth\n\nrouter = APIRouter(prefix="/api")\n\n\nclass Credentials(BaseModel):\n    username: str\n    password: str\n\n\n@router.post("/register", status_code=201)\ndef register(body: Credentials):\n    # TODO 1：调用 auth.register 并返回结果（出错时 AuthError 会被 main.py 里的处理函数接住）\n    pass\n\n\n@router.post("/login")\ndef login(body: Credentials, response: Response):\n    # TODO 2：调用 auth.login 得到令牌和用户；\n    #         response.set_cookie("session", 令牌, max_age=auth.SESSION_TTL, httponly=True, samesite="lax")，返回用户\n    pass\n\n\n@router.get("/me")\ndef me(request: Request):\n    # TODO 3：会话令牌是 request.cookies.get("session")，调用 auth.current_user 并返回结果\n    pass\n\n\n@router.post("/logout", status_code=204)\ndef logout(request: Request):\n    # TODO 4：调用 auth.logout；新建 Response(status_code=204)，\n    #         用 delete_cookie("session", httponly=True, samesite="lax") 删掉 Cookie，返回它\n    pass\n\n# main.py：导入 from app.routers import auth as auth_routes 和 from app.services.auth import AuthError，\n# 在 app.include_router(questions.router) 后面挂上账号路由，并加上 AuthError 的处理函数；\n# 原来 RequestValidationError 的提示文字改成 "请求参数不合法"\napp.include_router(auth_routes.router)\n\n\n@app.exception_handler(AuthError)\nasync def auth_error(request: Request, exc: AuthError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/routers/auth.py',to:'from app.services import auth',text:'账号接口的路由。Response 用来设置 Cookie；BaseModel 来自 FastAPI 自带的 pydantic 库，用来声明请求正文的格式。'},{at:'router = APIRouter(prefix="/api")',text:'这组路由都以 /api 开头。'},{at:'class Credentials(BaseModel):',to:'password: str',text:'请求正文的格式：两个字符串字段。函数参数写成 body: Credentials，FastAPI 就会把 JSON 正文解析成这个对象；缺字段或类型不对时自动拒绝（我们在 main.py 里把它统一成 400）。'},{at:'@router.post("/register", status_code=201)',to:'pass',text:'注册接口，要你补全。status_code=201 指定成功时的状态码。'},{at:'@router.post("/login")',to:'pass',text:'登录接口，要你补全。参数里声明 response: Response，FastAPI 会传进来一个响应对象，往它上面设置的 Cookie 会合并到最终的响应里。'},{at:'@router.get("/me")',to:'pass',text:'当前用户接口，要你补全。'},{at:'@router.post("/logout", status_code=204)',to:'pass',text:'退出接口，要你补全。'},{at:'app.include_router(auth_routes.router)',text:'挂上账号路由。auth 这个名字和 services 里的模块重名，导入时用 as 起一个别名。要写在兜底路由 /api/{rest:path} 前面。'},{at:'@app.exception_handler(AuthError)',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'任何路由里抛出 AuthError，都由这里按它带的状态码返回 {"error": …}。这样每个路由都不用写 try/except。'}],solution:{code:'# app/routers/auth.py\nfrom fastapi import APIRouter, Request, Response\nfrom pydantic import BaseModel\n\nfrom app.services import auth\n\nrouter = APIRouter(prefix="/api")\n\n\nclass Credentials(BaseModel):\n    username: str\n    password: str\n\n\n@router.post("/register", status_code=201)\ndef register(body: Credentials):\n    return auth.register(body.username, body.password)\n\n\n@router.post("/login")\ndef login(body: Credentials, response: Response):\n    token, user = auth.login(body.username, body.password)\n    response.set_cookie("session", token, max_age=auth.SESSION_TTL, httponly=True, samesite="lax")\n    return user\n\n\n@router.get("/me")\ndef me(request: Request):\n    return auth.current_user(request.cookies.get("session"))\n\n\n@router.post("/logout", status_code=204)\ndef logout(request: Request):\n    auth.logout(request.cookies.get("session"))\n    response = Response(status_code=204)\n    response.delete_cookie("session", httponly=True, samesite="lax")\n    return response\n\n# main.py：导入 from app.routers import auth as auth_routes 和 from app.services.auth import AuthError，\n# 在 app.include_router(questions.router) 后面挂上账号路由，并加上 AuthError 的处理函数；\n# 原来 RequestValidationError 的提示文字改成 "请求参数不合法"\napp.include_router(auth_routes.router)\n\n\n@app.exception_handler(AuthError)\nasync def auth_error(request: Request, exc: AuthError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/routers/auth.py',to:'from app.services import auth',text:'账号接口的路由。Response 用来设置 Cookie；BaseModel 来自 FastAPI 自带的 pydantic 库，用来声明请求正文的格式。'},{at:'router = APIRouter(prefix="/api")',text:'这组路由都以 /api 开头。'},{at:'class Credentials(BaseModel):',to:'password: str',text:'请求正文的格式：两个字符串字段。函数参数写成 body: Credentials，FastAPI 就会把 JSON 正文解析成这个对象；缺字段或类型不对时自动拒绝（我们在 main.py 里把它统一成 400）。'},{at:'@router.post("/register", status_code=201)',to:'return auth.register(body.username, body.password)',text:'交给业务逻辑层注册，成功返回 201 和用户。'},{at:'@router.post("/login")',to:'return user',text:'登录成功后在 response 上设置 Cookie，max_age 单位是秒。'},{at:'@router.get("/me")',to:'return auth.current_user(request.cookies.get("session"))',text:'按 Cookie 里的令牌找当前用户，没登录时业务层抛出 401。'},{at:'@router.post("/logout", status_code=204)',to:'return response',text:'删掉服务器上的会话，再让浏览器删掉 Cookie，返回 204（没有正文）。delete_cookie 的选项要和设置时一样，浏览器才认得是同一个 Cookie。'},{at:'app.include_router(auth_routes.router)',text:'挂上账号路由。auth 这个名字和 services 里的模块重名，导入时用 as 起一个别名。要写在兜底路由 /api/{rest:path} 前面。'},{at:'@app.exception_handler(AuthError)',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'任何路由里抛出 AuthError，都由这里按它带的状态码返回 {"error": …}。这样每个路由都不用写 try/except。'}]}}}},
  {title:'任务四：登录页面',body:'接口做好了，再给页面加上登录、注册和退出。按你选的前端做法显示具体写法。',variants:{html:{body:'新建一个登录页 login.html：输入用户名和密码，点“登录”就登录，点“注册”就先注册再自动登录，成功后回到首页。再写一个 user.js 放在首页上方：已登录时显示“你好，用户名”和“退出”按钮，没登录时显示“登录 / 注册”链接。\n这里第一次用 fetch 发 POST 请求，要指定 method、Content-Type 请求头和 JSON 正文。Cookie 不用我们操心：同源请求时浏览器会自动保存和发送，而且它是 HttpOnly 的，JS 本来也读不到。',practice:{steps:['在静态目录里新建 login.html 和 login.js（代码前两部分），补完 TODO。','新建 user.js（第三部分），按注释在 index.html 里加上用户栏和脚本。','打开首页，点“登录 / 注册”，注册一个新账号，回到首页看到“你好，用户名”；点退出，再登录一次；故意输错密码看看提示。'],expect:'面试自习室\n你好，tom [退出]\n[搜索题目      ] [搜索]\n…'},code:'<!-- login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>登录 / 注册</h1>\n  <form id="auth">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  <p id="message"></p>\n  <script src="login.js"></script>\n</body>\n</html>\n\n// login.js\nconst form = document.getElementById("auth");\nconst message = document.getElementById("message");\n\nasync function post(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data?.error || "请求失败");\n  return data;\n}\n\nform.addEventListener("submit", async (event) => {\n  event.preventDefault();\n  // TODO 1：用 FormData 读出用户名（去掉首尾空格）和密码\n  // TODO 2：event.submitter 是被点的按钮：它的 value 是 "register" 时先调用 /api/register 注册；\n  //         然后调用 /api/login 登录，成功后用 location.href = "/" 回到首页\n  // TODO 3：任何一步失败（用 try / catch），在 message 里显示错误信息 err.message\n});\n\n// user.js（在 index.html 的 <h1> 下面加上 <p id="user"></p>，在 app.js 前面加上 <script src="user.js"></script>）\nconst userBox = document.getElementById("user");\n\nasync function showUser() {\n  const res = await fetch("/api/me");\n  if (!res.ok) {\n    userBox.innerHTML = \'<a href="login.html">登录 / 注册</a>\';\n    return;\n  }\n  const me = await res.json();\n  const logout = document.createElement("button");\n  logout.textContent = "退出";\n  logout.addEventListener("click", async () => {\n    await fetch("/api/logout", { method: "POST" });\n    location.reload();\n  });\n  userBox.replaceChildren(`你好，${me.username} `, logout);\n}\n\nshowUser();',explain:[{at:'<!-- login.html -->',to:'</head>',text:'新建的登录页。'},{at:'<body>',to:'<h1>登录 / 注册</h1>',text:'返回链接和标题。'},{at:'<form id="auth">',to:'</form>',text:'一个表单两个按钮：两个按钮的 name 都是 action，value 不同，JS 根据点的是哪个按钮决定调用登录还是注册。type="password" 的输入框会把输入显示成圆点；required 表示不填不能提交。'},{at:'<p id="message"></p>',text:'显示提示信息，比如“用户名或密码错误”。'},{at:'<script src="login.js"></script>',to:'</html>',text:'加载登录页的脚本。'},{at:'// login.js',to:'const message = document.getElementById("message");',text:'找到表单和提示信息的元素。'},{at:'async function post(url, body) {',to:'body: JSON.stringify(body),',text:'发 POST 请求：fetch 的第二个参数可以指定方法、请求头和正文。JSON.stringify 把对象转成 JSON 字符串。同源请求时，浏览器会自动保存响应里的 Cookie，之后的请求也自动带上。'},{at:'const data = res.status === 204 ? null : await res.json();',to:'return data;',text:'204 没有正文，不能解析。失败时把后端返回的 error 当作错误信息抛出。data?.error 中的 ?. 表示 data 是 null 时不报错，直接得到 undefined。'},{at:'form.addEventListener("submit", async (event) => {',to:'event.preventDefault();',text:'表单提交时由我们自己处理，要你补全。'},{at:'// user.js',to:'const userBox = document.getElementById("user");',text:'首页上方的用户栏，单独放一个文件，以后别的页面也能用。'},{at:'async function showUser() {',to:'return;',text:'问后端“我是谁”。没登录（401）时显示登录链接。这里的 HTML 是我们自己写死的，不含任何数据，所以用 innerHTML 是安全的。'},{at:'const me = await res.json();',to:'location.reload();',text:'登录了：创建一个“退出”按钮，点击时调用退出接口，再刷新页面。'},{at:'userBox.replaceChildren(`你好，${me.username} `, logout);',text:'replaceChildren 可以同时放文字和元素。用户名作为文字放进去，不会被当成 HTML。'},{at:'showUser();',text:'页面打开时执行一次。'}],solution:{code:'<!-- login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>登录 / 注册</h1>\n  <form id="auth">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  <p id="message"></p>\n  <script src="login.js"></script>\n</body>\n</html>\n\n// login.js\nconst form = document.getElementById("auth");\nconst message = document.getElementById("message");\n\nasync function post(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data?.error || "请求失败");\n  return data;\n}\n\nform.addEventListener("submit", async (event) => {\n  event.preventDefault();\n  const fields = new FormData(form);\n  const body = { username: fields.get("username").trim(), password: fields.get("password") };\n  try {\n    if (event.submitter.value === "register") {\n      await post("/api/register", body);\n    }\n    await post("/api/login", body);\n    location.href = "/";\n  } catch (err) {\n    message.textContent = err.message;\n  }\n});\n\n// user.js（在 index.html 的 <h1> 下面加上 <p id="user"></p>，在 app.js 前面加上 <script src="user.js"></script>）\nconst userBox = document.getElementById("user");\n\nasync function showUser() {\n  const res = await fetch("/api/me");\n  if (!res.ok) {\n    userBox.innerHTML = \'<a href="login.html">登录 / 注册</a>\';\n    return;\n  }\n  const me = await res.json();\n  const logout = document.createElement("button");\n  logout.textContent = "退出";\n  logout.addEventListener("click", async () => {\n    await fetch("/api/logout", { method: "POST" });\n    location.reload();\n  });\n  userBox.replaceChildren(`你好，${me.username} `, logout);\n}\n\nshowUser();',explain:[{at:'<!-- login.html -->',to:'</head>',text:'新建的登录页。'},{at:'<body>',to:'<h1>登录 / 注册</h1>',text:'返回链接和标题。'},{at:'<form id="auth">',to:'</form>',text:'一个表单两个按钮：两个按钮的 name 都是 action，value 不同，JS 根据点的是哪个按钮决定调用登录还是注册。type="password" 的输入框会把输入显示成圆点；required 表示不填不能提交。'},{at:'<p id="message"></p>',text:'显示提示信息，比如“用户名或密码错误”。'},{at:'<script src="login.js"></script>',to:'</html>',text:'加载登录页的脚本。'},{at:'// login.js',to:'const message = document.getElementById("message");',text:'找到表单和提示信息的元素。'},{at:'async function post(url, body) {',to:'body: JSON.stringify(body),',text:'发 POST 请求：fetch 的第二个参数可以指定方法、请求头和正文。JSON.stringify 把对象转成 JSON 字符串。同源请求时，浏览器会自动保存响应里的 Cookie，之后的请求也自动带上。'},{at:'const data = res.status === 204 ? null : await res.json();',to:'return data;',text:'204 没有正文，不能解析。失败时把后端返回的 error 当作错误信息抛出。data?.error 中的 ?. 表示 data 是 null 时不报错，直接得到 undefined。'},{at:'form.addEventListener("submit", async (event) => {',to:'const body = { username: fields.get("username").trim(), password: fields.get("password") };',text:'阻止默认提交，读出用户名和密码。密码不去空格：空格也可能是密码的一部分。'},{at:'try {',to:'location.href = "/";',text:'event.submitter 是触发提交的按钮。注册成功后接着登录，登录成功后跳回首页（给 location.href 赋值就是跳转）。'},{at:'} catch (err) {',to:'message.textContent = err.message;',text:'显示后端返回的错误，比如“用户名已被注册”“用户名或密码错误”。'},{at:'// user.js',to:'const userBox = document.getElementById("user");',text:'首页上方的用户栏，单独放一个文件，以后别的页面也能用。'},{at:'async function showUser() {',to:'return;',text:'问后端“我是谁”。没登录（401）时显示登录链接。这里的 HTML 是我们自己写死的，不含任何数据，所以用 innerHTML 是安全的。'},{at:'const me = await res.json();',to:'location.reload();',text:'登录了：创建一个“退出”按钮，点击时调用退出接口，再刷新页面。'},{at:'userBox.replaceChildren(`你好，${me.username} `, logout);',text:'replaceChildren 可以同时放文字和元素。用户名作为文字放进去，不会被当成 HTML。'},{at:'showUser();',text:'页面打开时执行一次。'}]}},react:{body:'新增两个组件：UserBar 放在每个页面上方，已登录时显示“你好，用户名”和“退出”，没登录时显示“登录 / 注册”链接；LoginPage 是登录页，地址是 /?page=login，点“登录”就登录，点“注册”就先注册再自动登录，成功后回到首页。\n这里第一次用 fetch 发 POST 请求，要指定 method、Content-Type 请求头和 JSON 正文。Cookie 不用我们操心：同源请求时浏览器会自动保存和发送（开发时 Vite 代理转发也一样），而且它是 HttpOnly 的，JS 本来也读不到。',practice:{steps:['把 src/App.jsx 换成代码第一部分。','新建 src/UserBar.jsx（第二部分）和 src/LoginPage.jsx（第三部分），补完 TODO。','npm run dev，点“登录 / 注册”，注册一个新账号，回到首页看到“你好，用户名”；点退出，再登录一次；故意输错密码看看提示。完成后 npm run build。'],expect:'你好，tom [退出]\n面试自习室\n[搜索题目      ] [搜索]\n…'},code:'// src/App.jsx\nimport LoginPage from "./LoginPage.jsx";\nimport QuestionDetail from "./QuestionDetail.jsx";\nimport QuestionList from "./QuestionList.jsx";\nimport UserBar from "./UserBar.jsx";\n\nexport default function App() {\n  const params = new URLSearchParams(window.location.search);\n  if (params.get("page") === "login") return <LoginPage />;\n  const id = params.get("id");\n  return (\n    <>\n      <UserBar />\n      {id ? <QuestionDetail id={id} /> : <QuestionList />}\n    </>\n  );\n}\n\n// src/UserBar.jsx\nimport { useEffect, useState } from "react";\n\nexport default function UserBar() {\n  const [user, setUser] = useState(null);\n\n  useEffect(() => {\n    fetch("/api/me")\n      .then((res) => (res.ok ? res.json() : null))\n      .then(setUser)\n      .catch(() => {});\n  }, []);\n\n  async function logout() {\n    await fetch("/api/logout", { method: "POST" });\n    window.location.reload();\n  }\n\n  if (!user) return <p><a href="/?page=login">登录 / 注册</a></p>;\n  return (\n    <p>\n      你好，{user.username} <button onClick={logout}>退出</button>\n    </p>\n  );\n}\n\n// src/LoginPage.jsx\nimport { useState } from "react";\n\nasync function post(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = await res.json();\n  if (!res.ok) throw new Error(data.error || "请求失败");\n  return data;\n}\n\nexport default function LoginPage() {\n  const [username, setUsername] = useState("");\n  const [password, setPassword] = useState("");\n  const [message, setMessage] = useState("");\n\n  async function submit(event, action) {\n    event.preventDefault();\n    // TODO：action 是 "register" 时先 post("/api/register", …)；然后 post("/api/login", …)，\n    //       成功后 window.location.href = "/"；失败时 setMessage(err.message)。用户名记得去掉首尾空格\n  }\n\n  return (\n    <main>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>登录 / 注册</h1>\n      <form onSubmit={(e) => submit(e, "login")}>\n        <p><input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="用户名" required /></p>\n        <p><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="密码（至少 8 位）" required /></p>\n        <button>登录</button> <button type="button" onClick={(e) => submit(e, "register")}>注册</button>\n      </form>\n      {message && <p>{message}</p>}\n    </main>\n  );\n}',explain:[{at:'// src/App.jsx',to:'import UserBar from "./UserBar.jsx";',text:'App 多认识两个组件：登录页和用户栏。'},{at:'export default function App() {',to:'if (params.get("page") === "login") return <LoginPage />;',text:'地址是 /?page=login 时显示登录页。'},{at:'const id = params.get("id");',to:'{id ? <QuestionDetail id={id} /> : <QuestionList />}',text:'其他页面上方都显示用户栏。<></> 把两个组件包成一组。'},{at:'</>',to:'}',text:'组件结束。'},{at:'// src/UserBar.jsx',to:'import { useEffect, useState } from "react";',text:'用户栏组件。'},{at:'export default function UserBar() {',to:'const [user, setUser] = useState(null);',text:'状态：当前用户，没登录时是 null。'},{at:'useEffect(() => {',to:'}, []);',text:'组件第一次显示时问后端“我是谁”：成功就保存用户，401 时保持 null。'},{at:'async function logout() {',to:'window.location.reload();',text:'退出：调用退出接口，再刷新页面。'},{at:'if (!user) return <p><a href="/?page=login">登录 / 注册</a></p>;',text:'没登录时显示登录链接。'},{at:'return (',to:'</p>',text:'登录了：显示用户名和退出按钮。'},{at:'// src/LoginPage.jsx',to:'import { useState } from "react";',text:'登录页组件。'},{at:'async function post(url, body) {',to:'return data;',text:'发 POST 请求：指定方法、Content-Type 请求头和 JSON 正文。失败时把后端返回的 error 当作错误信息抛出。同源请求时，浏览器会自动保存响应里的 Cookie。'},{at:'export default function LoginPage() {',to:'const [message, setMessage] = useState("");',text:'三个状态：两个输入框的内容和提示信息。'},{at:'async function submit(event, action) {',to:'event.preventDefault();',text:'登录和注册共用的提交函数，要你补全。'},{at:'return (',to:'<h1>登录 / 注册</h1>',text:'返回链接和标题。'},{at:'<form onSubmit={(e) => submit(e, "login")}>',to:'</form>',text:'两个受控输入框。按回车或点“登录”会提交表单，执行登录；“注册”按钮写了 type="button"，不会提交表单，点击时直接调用 submit 并告诉它要注册。'},{at:'{message && <p>{message}</p>}',to:'</main>',text:'有提示信息时显示出来。'}],solution:{code:'// src/App.jsx\nimport LoginPage from "./LoginPage.jsx";\nimport QuestionDetail from "./QuestionDetail.jsx";\nimport QuestionList from "./QuestionList.jsx";\nimport UserBar from "./UserBar.jsx";\n\nexport default function App() {\n  const params = new URLSearchParams(window.location.search);\n  if (params.get("page") === "login") return <LoginPage />;\n  const id = params.get("id");\n  return (\n    <>\n      <UserBar />\n      {id ? <QuestionDetail id={id} /> : <QuestionList />}\n    </>\n  );\n}\n\n// src/UserBar.jsx\nimport { useEffect, useState } from "react";\n\nexport default function UserBar() {\n  const [user, setUser] = useState(null);\n\n  useEffect(() => {\n    fetch("/api/me")\n      .then((res) => (res.ok ? res.json() : null))\n      .then(setUser)\n      .catch(() => {});\n  }, []);\n\n  async function logout() {\n    await fetch("/api/logout", { method: "POST" });\n    window.location.reload();\n  }\n\n  if (!user) return <p><a href="/?page=login">登录 / 注册</a></p>;\n  return (\n    <p>\n      你好，{user.username} <button onClick={logout}>退出</button>\n    </p>\n  );\n}\n\n// src/LoginPage.jsx\nimport { useState } from "react";\n\nasync function post(url, body) {\n  const res = await fetch(url, {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify(body),\n  });\n  const data = await res.json();\n  if (!res.ok) throw new Error(data.error || "请求失败");\n  return data;\n}\n\nexport default function LoginPage() {\n  const [username, setUsername] = useState("");\n  const [password, setPassword] = useState("");\n  const [message, setMessage] = useState("");\n\n  async function submit(event, action) {\n    event.preventDefault();\n    const body = { username: username.trim(), password };\n    try {\n      if (action === "register") await post("/api/register", body);\n      await post("/api/login", body);\n      window.location.href = "/";\n    } catch (err) {\n      setMessage(err.message);\n    }\n  }\n\n  return (\n    <main>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>登录 / 注册</h1>\n      <form onSubmit={(e) => submit(e, "login")}>\n        <p><input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="用户名" required /></p>\n        <p><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="密码（至少 8 位）" required /></p>\n        <button>登录</button> <button type="button" onClick={(e) => submit(e, "register")}>注册</button>\n      </form>\n      {message && <p>{message}</p>}\n    </main>\n  );\n}',explain:[{at:'// src/App.jsx',to:'import UserBar from "./UserBar.jsx";',text:'App 多认识两个组件：登录页和用户栏。'},{at:'export default function App() {',to:'if (params.get("page") === "login") return <LoginPage />;',text:'地址是 /?page=login 时显示登录页。'},{at:'const id = params.get("id");',to:'{id ? <QuestionDetail id={id} /> : <QuestionList />}',text:'其他页面上方都显示用户栏。<></> 把两个组件包成一组。'},{at:'</>',to:'}',text:'组件结束。'},{at:'// src/UserBar.jsx',to:'import { useEffect, useState } from "react";',text:'用户栏组件。'},{at:'export default function UserBar() {',to:'const [user, setUser] = useState(null);',text:'状态：当前用户，没登录时是 null。'},{at:'useEffect(() => {',to:'}, []);',text:'组件第一次显示时问后端“我是谁”：成功就保存用户，401 时保持 null。'},{at:'async function logout() {',to:'window.location.reload();',text:'退出：调用退出接口，再刷新页面。'},{at:'if (!user) return <p><a href="/?page=login">登录 / 注册</a></p>;',text:'没登录时显示登录链接。'},{at:'return (',to:'</p>',text:'登录了：显示用户名和退出按钮。'},{at:'// src/LoginPage.jsx',to:'import { useState } from "react";',text:'登录页组件。'},{at:'async function post(url, body) {',to:'return data;',text:'发 POST 请求：指定方法、Content-Type 请求头和 JSON 正文。失败时把后端返回的 error 当作错误信息抛出。同源请求时，浏览器会自动保存响应里的 Cookie。'},{at:'export default function LoginPage() {',to:'const [message, setMessage] = useState("");',text:'三个状态：两个输入框的内容和提示信息。'},{at:'async function submit(event, action) {',to:'const body = { username: username.trim(), password };',text:'阻止默认提交，准备正文。密码不去空格：空格也可能是密码的一部分。'},{at:'try {',to:'window.location.href = "/";',text:'注册时先注册，然后都要登录，成功后跳回首页。'},{at:'} catch (err) {',to:'setMessage(err.message);',text:'显示后端返回的错误，比如“用户名已被注册”“用户名或密码错误”。'},{at:'return (',to:'<h1>登录 / 注册</h1>',text:'返回链接和标题。'},{at:'<form onSubmit={(e) => submit(e, "login")}>',to:'</form>',text:'两个受控输入框。按回车或点“登录”会提交表单，执行登录；“注册”按钮写了 type="button"，不会提交表单，点击时直接调用 submit 并告诉它要注册。'},{at:'{message && <p>{message}</p>}',to:'</main>',text:'有提示信息时显示出来。'}]}},'template-go':{body:'模板渲染不写前端 JS，登录、注册、退出都用普通的 HTML 表单提交：表单用 POST 方式提交到后端，后端调用和 JSON 接口同一个业务逻辑层，成功后设置 Cookie，再让浏览器“重定向”（跳转）回首页；失败时重新显示登录页和错误信息。\n重定向用 303 See Other：它告诉浏览器“去用 GET 打开另一个地址”。这样用户刷新首页时，不会弹出“是否重新提交表单”。这种“提交后重定向”的做法有个名字：PRG（Post/Redirect/Get）。\n会话 Cookie 是 SameSite=Lax 的，别的网站偷偷向 /login、/logout 提交表单时，浏览器不会带上它，可以防住大部分 CSRF 攻击。',practice:{steps:['新建 internal/handler/pages_auth.go，补完 TODO，在 Routes 里注册三个路由。','新建 web/templates/login.html，在首页模板里加上入口链接。','打开 /login 注册一个新账号，回到首页；再打开 /login 能看到“你好”和退出按钮；故意输错密码看看提示。'],expect:'登录 / 注册\n[用户名      ]\n[密码        ]\n[登录] [注册]'},code:'// internal/handler/pages_auth.go（Routes 里加上三行：\n//   mux.HandleFunc("GET /login", h.loginPage)\n//   mux.HandleFunc("POST /login", h.loginForm)\n//   mux.HandleFunc("POST /logout", h.logoutForm)）\npackage handler\n\nimport (\n    "errors"\n    "net/http"\n    "strings"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\nfunc (h *Handler) loginPage(w http.ResponseWriter, r *http.Request) {\n    data := map[string]any{}\n    if u, err := h.auth.CurrentUser(sessionToken(r)); err == nil {\n        data["User"] = u\n    }\n    h.render(w, http.StatusOK, "login.html", data)\n}\n\n// loginFailed 把错误显示在登录页上，状态码和接口保持一致。\nfunc (h *Handler) loginFailed(w http.ResponseWriter, err error) {\n    status, msg := http.StatusBadRequest, err.Error()\n    switch {\n    case errors.Is(err, store.ErrUsernameTaken):\n        status, msg = http.StatusConflict, "用户名已被注册"\n    case errors.Is(err, service.ErrBadCredentials):\n        status = http.StatusUnauthorized\n    case !errors.Is(err, service.ErrInvalidInput):\n        h.serverError(w, err)\n        return\n    }\n    h.render(w, status, "login.html", map[string]any{"Error": msg})\n}\n\nfunc (h *Handler) loginForm(w http.ResponseWriter, r *http.Request) {\n    // TODO 1：用 r.FormValue 读出 username（去掉首尾空格）、password 和 action\n    // TODO 2：action 是 "register" 时先 h.auth.Register，出错交给 h.loginFailed\n    // TODO 3：h.auth.Login，出错交给 h.loginFailed；成功时 setSession，再用\n    //         http.Redirect(w, r, "/", http.StatusSeeOther) 跳回首页\n}\n\nfunc (h *Handler) logoutForm(w http.ResponseWriter, r *http.Request) {\n    // TODO 4：h.auth.Logout(sessionToken(r))，clearSession(w)，跳回首页\n}\n\n<!-- web/templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  {{if .User}}\n  <p>你好，{{.User.Username}}</p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  {{else}}\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  {{if .Error}}<p>{{.Error}}</p>{{end}}\n  {{end}}\n</body>\n</html>\n\n<!-- web/templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// internal/handler/pages_auth.go',to:'"zixishi/internal/store"',text:'登录页相关的处理函数放在一个新文件里，和 JSON 接口一样调用业务逻辑层，只是输入来自表单、输出是页面。'},{at:'func (h *Handler) loginPage(',to:'h.render(w, http.StatusOK, "login.html", data)',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时显示表单。'},{at:'func (h *Handler) loginFailed(',to:'h.render(w, status, "login.html", map[string]any{"Error": msg})',text:'出错时重新显示登录页和错误信息。参数不合格 400、用户名已存在 409、密码错误 401，其他错误 500。'},{at:'func (h *Handler) loginForm(',text:'处理登录表单，要你补全。'},{at:'func (h *Handler) logoutForm(',text:'处理退出表单，要你补全。'},{at:'<!-- web/templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'{{if .User}}',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'{{else}}',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'{{if .Error}}<p>{{.Error}}</p>{{end}}',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- web/templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}],solution:{code:'// internal/handler/pages_auth.go（Routes 里加上三行：\n//   mux.HandleFunc("GET /login", h.loginPage)\n//   mux.HandleFunc("POST /login", h.loginForm)\n//   mux.HandleFunc("POST /logout", h.logoutForm)）\npackage handler\n\nimport (\n    "errors"\n    "net/http"\n    "strings"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\nfunc (h *Handler) loginPage(w http.ResponseWriter, r *http.Request) {\n    data := map[string]any{}\n    if u, err := h.auth.CurrentUser(sessionToken(r)); err == nil {\n        data["User"] = u\n    }\n    h.render(w, http.StatusOK, "login.html", data)\n}\n\n// loginFailed 把错误显示在登录页上，状态码和接口保持一致。\nfunc (h *Handler) loginFailed(w http.ResponseWriter, err error) {\n    status, msg := http.StatusBadRequest, err.Error()\n    switch {\n    case errors.Is(err, store.ErrUsernameTaken):\n        status, msg = http.StatusConflict, "用户名已被注册"\n    case errors.Is(err, service.ErrBadCredentials):\n        status = http.StatusUnauthorized\n    case !errors.Is(err, service.ErrInvalidInput):\n        h.serverError(w, err)\n        return\n    }\n    h.render(w, status, "login.html", map[string]any{"Error": msg})\n}\n\nfunc (h *Handler) loginForm(w http.ResponseWriter, r *http.Request) {\n    username, password := strings.TrimSpace(r.FormValue("username")), r.FormValue("password")\n    if r.FormValue("action") == "register" {\n        if _, err := h.auth.Register(username, password); err != nil {\n            h.loginFailed(w, err)\n            return\n        }\n    }\n    token, _, err := h.auth.Login(username, password)\n    if err != nil {\n        h.loginFailed(w, err)\n        return\n    }\n    setSession(w, token)\n    http.Redirect(w, r, "/", http.StatusSeeOther)\n}\n\nfunc (h *Handler) logoutForm(w http.ResponseWriter, r *http.Request) {\n    if err := h.auth.Logout(sessionToken(r)); err != nil {\n        h.serverError(w, err)\n        return\n    }\n    clearSession(w)\n    http.Redirect(w, r, "/", http.StatusSeeOther)\n}\n\n<!-- web/templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  {{if .User}}\n  <p>你好，{{.User.Username}}</p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  {{else}}\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  {{if .Error}}<p>{{.Error}}</p>{{end}}\n  {{end}}\n</body>\n</html>\n\n<!-- web/templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// internal/handler/pages_auth.go',to:'"zixishi/internal/store"',text:'登录页相关的处理函数放在一个新文件里，和 JSON 接口一样调用业务逻辑层，只是输入来自表单、输出是页面。'},{at:'func (h *Handler) loginPage(',to:'h.render(w, http.StatusOK, "login.html", data)',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时显示表单。'},{at:'func (h *Handler) loginFailed(',to:'h.render(w, status, "login.html", map[string]any{"Error": msg})',text:'出错时重新显示登录页和错误信息。参数不合格 400、用户名已存在 409、密码错误 401，其他错误 500。'},{at:'func (h *Handler) loginForm(',to:'username, password := strings.TrimSpace(r.FormValue("username")), r.FormValue("password")',text:'FormValue 读取表单字段（也能读地址里的参数）。'},{at:'if r.FormValue("action") == "register" {',to:'return',text:'点的是“注册”时先注册。'},{at:'token, _, err := h.auth.Login(username, password)',to:'http.Redirect(w, r, "/", http.StatusSeeOther)',text:'登录成功：设置 Cookie，用 303 重定向回首页。Redirect 会写好 Location 响应头和状态码。'},{at:'func (h *Handler) logoutForm(',to:'http.Redirect(w, r, "/", http.StatusSeeOther)',text:'退出：删掉会话和 Cookie，回到首页。'},{at:'<!-- web/templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'{{if .User}}',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'{{else}}',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'{{if .Error}}<p>{{.Error}}</p>{{end}}',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- web/templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}]}},'template-node':{body:'模板渲染不写前端 JS，登录、注册、退出都用普通的 HTML 表单提交：表单用 POST 方式提交到后端，后端调用和 JSON 接口同一个业务逻辑层，成功后设置 Cookie，再让浏览器“重定向”（跳转）回首页；失败时重新显示登录页和错误信息。\n重定向用 303 See Other：它告诉浏览器“去用 GET 打开另一个地址”。这样用户刷新首页时，不会弹出“是否重新提交表单”。这种“提交后重定向”的做法有个名字：PRG（Post/Redirect/Get）。\n会话 Cookie 是 SameSite=Lax 的，别的网站偷偷向 /login、/logout 提交表单时，浏览器不会带上它，可以防住大部分 CSRF 攻击。',practice:{steps:['按代码第一部分修改 app.js，补完 TODO。','新建 views/login.ejs，在首页模板里加上入口链接。','打开 /login 注册一个新账号，回到首页；再打开 /login 能看到“你好”和退出按钮；故意输错密码看看提示。'],expect:'登录 / 注册\n[用户名      ]\n[密码        ]\n[登录] [注册]'},code:'// app.js：在 app.use(express.json()) 后面加上 app.use(express.urlencoded({ extended: false }))，\n// 顶部导入 const auth = require("./src/services/auth")，再在 app.use("/api", notFound) 前面加上：\napp.get("/login", (req, res) => {\n  let user = null;\n  try {\n    user = auth.currentUser(req.cookies.session);\n  } catch {\n    // 没登录，显示表单\n  }\n  res.render("login", { user, error: "" });\n});\n\napp.post("/login", (req, res, next) => {\n  // TODO 1：从 req.body 读出 username（去掉首尾空格）、password 和 action\n  // TODO 2：action 是 "register" 时先 auth.register；然后 auth.login，设置 Cookie（选项和 API 的登录一样），\n  //         用 res.redirect(303, "/") 跳回首页\n  // TODO 3：出错时：是 auth.AuthError 就用它的状态码重新渲染 login，传入 { user: null, error: err.message }；\n  //         其他错误交给 next(err)\n});\n\napp.post("/logout", (req, res) => {\n  // TODO 4：auth.logout，res.clearCookie 删掉 Cookie，跳回首页\n});\n\n<!-- views/login.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <% if (user) { %>\n  <p>你好，<%= user.username %></p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  <% } else { %>\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  <% if (error) { %><p><%= error %></p><% } %>\n  <% } %>\n</body>\n</html>\n\n<!-- views/index.ejs：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// app.js',text:'express.urlencoded 解析表单提交的请求正文（格式是 username=tom&password=…），结果同样放进 req.body。'},{at:'app.get("/login", (req, res) => {',to:'res.render("login", { user, error: "" });',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 currentUser 抛出错误，user 保持 null，显示表单。'},{at:'app.post("/login", (req, res, next) => {',text:'处理登录表单，要你补全。'},{at:'app.post("/logout", (req, res) => {',text:'处理退出表单，要你补全。'},{at:'<!-- views/login.ejs -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'<% if (user) { %>',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'<% } else { %>',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'<% if (error) { %>',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- views/index.ejs：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}],solution:{code:'// app.js：在 app.use(express.json()) 后面加上 app.use(express.urlencoded({ extended: false }))，\n// 顶部导入 const auth = require("./src/services/auth")，再在 app.use("/api", notFound) 前面加上：\napp.get("/login", (req, res) => {\n  let user = null;\n  try {\n    user = auth.currentUser(req.cookies.session);\n  } catch {\n    // 没登录，显示表单\n  }\n  res.render("login", { user, error: "" });\n});\n\napp.post("/login", (req, res, next) => {\n  const username = (req.body.username || "").trim();\n  const password = req.body.password || "";\n  try {\n    if (req.body.action === "register") auth.register(username, password);\n    const { token } = auth.login(username, password);\n    res.cookie("session", token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: auth.SESSION_TTL });\n    res.redirect(303, "/");\n  } catch (err) {\n    if (!(err instanceof auth.AuthError)) return next(err);\n    res.status(err.status).render("login", { user: null, error: err.message });\n  }\n});\n\napp.post("/logout", (req, res) => {\n  auth.logout(req.cookies.session);\n  res.clearCookie("session", { httpOnly: true, sameSite: "lax", path: "/" });\n  res.redirect(303, "/");\n});\n\n<!-- views/login.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <% if (user) { %>\n  <p>你好，<%= user.username %></p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  <% } else { %>\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  <% if (error) { %><p><%= error %></p><% } %>\n  <% } %>\n</body>\n</html>\n\n<!-- views/index.ejs：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// app.js',text:'express.urlencoded 解析表单提交的请求正文（格式是 username=tom&password=…），结果同样放进 req.body。'},{at:'app.get("/login", (req, res) => {',to:'res.render("login", { user, error: "" });',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 currentUser 抛出错误，user 保持 null，显示表单。'},{at:'app.post("/login", (req, res, next) => {',to:'const password = req.body.password || "";',text:'读出表单字段，没填时用空字符串。'},{at:'try {',to:'res.redirect(303, "/");',text:'点的是“注册”时先注册，然后登录、设置 Cookie，用 303 重定向回首页。'},{at:'} catch (err) {',to:'res.status(err.status).render("login", { user: null, error: err.message });',text:'业务错误就带着状态码重新显示登录页；其他意外错误交给错误处理中间件。'},{at:'app.post("/logout", (req, res) => {',to:'res.redirect(303, "/");',text:'退出：删掉会话和 Cookie，回到首页。'},{at:'<!-- views/login.ejs -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'<% if (user) { %>',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'<% } else { %>',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'<% if (error) { %>',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- views/index.ejs：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}]}},'template-python':{body:'模板渲染不写前端 JS，登录、注册、退出都用普通的 HTML 表单提交：表单用 POST 方式提交到后端，后端调用和 JSON 接口同一个业务逻辑层，成功后设置 Cookie，再让浏览器“重定向”（跳转）回首页；失败时重新显示登录页和错误信息。\n重定向用 303 See Other：它告诉浏览器“去用 GET 打开另一个地址”。这样用户刷新首页时，不会弹出“是否重新提交表单”。这种“提交后重定向”的做法有个名字：PRG（Post/Redirect/Get）。\n会话 Cookie 是 SameSite=Lax 的，别的网站偷偷向 /login、/logout 提交表单时，浏览器不会带上它，可以防住大部分 CSRF 攻击。',practice:{steps:['运行 pip install python-multipart，按代码第一部分修改 main.py，补完 TODO。','新建 templates/login.html，在首页模板里加上入口链接。','打开 /login 注册一个新账号，回到首页；再打开 /login 能看到“你好”和退出按钮；故意输错密码看看提示。'],expect:'登录 / 注册\n[用户名      ]\n[密码        ]\n[登录] [注册]'},code:'# main.py：先运行 pip install python-multipart（FastAPI 读取表单要用它），\n# 导入 from fastapi import Form、from fastapi.responses import RedirectResponse 和 from app.services import auth，\n# 再在兜底路由前面加上：\n@app.get("/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    try:\n        user = auth.current_user(request.cookies.get("session"))\n    except auth.AuthError:\n        user = None\n    return templates.TemplateResponse(request, "login.html", {"user": user, "error": ""})\n\n\n@app.post("/login", response_class=HTMLResponse)\ndef login_form(request: Request, username: str = Form(""), password: str = Form(""), action: str = Form("login")):\n    # TODO 1：action 是 "register" 时先 auth.register；然后 auth.login（用户名去掉首尾空格）\n    # TODO 2：出现 auth.AuthError 时，用它的状态码重新渲染 login.html，数据是 {"user": None, "error": e.message}\n    # TODO 3：成功时创建 RedirectResponse("/", status_code=303)，在它上面设置 Cookie（选项和 API 的登录一样），返回它\n    pass\n\n\n@app.post("/logout")\ndef logout_form(request: Request):\n    # TODO 4：auth.logout，创建 303 重定向到首页的响应，delete_cookie 删掉 Cookie，返回它\n    pass\n\n<!-- templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  {% if user %}\n  <p>你好，{{ user.username }}</p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  {% else %}\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  {% if error %}<p>{{ error }}</p>{% endif %}\n  {% endif %}\n</body>\n</html>\n\n<!-- templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'# main.py',text:'FastAPI 读取表单字段要用 Form，它依赖 python-multipart 这个库。装完记得更新 requirements.txt。'},{at:'@app.get("/login", response_class=HTMLResponse)',to:'return templates.TemplateResponse(request, "login.html", {"user": user, "error": ""})',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 current_user 抛出 AuthError，user 设成 None，显示表单。'},{at:'@app.post("/login", response_class=HTMLResponse)',to:'    pass',text:'处理登录表单，要你补全。Form("") 表示这个参数从表单字段里读取，没有时是空字符串。'},{at:'@app.post("/logout")',to:'    pass',text:'处理退出表单，要你补全。'},{at:'<!-- templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'{% if user %}',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'{% else %}',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'{% if error %}',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}],solution:{code:'# main.py：先运行 pip install python-multipart（FastAPI 读取表单要用它），\n# 导入 from fastapi import Form、from fastapi.responses import RedirectResponse 和 from app.services import auth，\n# 再在兜底路由前面加上：\n@app.get("/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    try:\n        user = auth.current_user(request.cookies.get("session"))\n    except auth.AuthError:\n        user = None\n    return templates.TemplateResponse(request, "login.html", {"user": user, "error": ""})\n\n\n@app.post("/login", response_class=HTMLResponse)\ndef login_form(request: Request, username: str = Form(""), password: str = Form(""), action: str = Form("login")):\n    try:\n        if action == "register":\n            auth.register(username.strip(), password)\n        token, _ = auth.login(username.strip(), password)\n    except auth.AuthError as e:\n        return templates.TemplateResponse(request, "login.html", {"user": None, "error": e.message},\n                                          status_code=e.status)\n    response = RedirectResponse("/", status_code=303)\n    response.set_cookie("session", token, max_age=auth.SESSION_TTL, httponly=True, samesite="lax")\n    return response\n\n\n@app.post("/logout")\ndef logout_form(request: Request):\n    auth.logout(request.cookies.get("session"))\n    response = RedirectResponse("/", status_code=303)\n    response.delete_cookie("session", httponly=True, samesite="lax")\n    return response\n\n<!-- templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  {% if user %}\n  <p>你好，{{ user.username }}</p>\n  <form method="post" action="/logout"><button>退出</button></form>\n  {% else %}\n  <h1>登录 / 注册</h1>\n  <form method="post" action="/login">\n    <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n    <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n    <button name="action" value="login">登录</button>\n    <button name="action" value="register">注册</button>\n  </form>\n  {% if error %}<p>{{ error }}</p>{% endif %}\n  {% endif %}\n</body>\n</html>\n\n<!-- templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'# main.py',text:'FastAPI 读取表单字段要用 Form，它依赖 python-multipart 这个库。装完记得更新 requirements.txt。'},{at:'@app.get("/login", response_class=HTMLResponse)',to:'return templates.TemplateResponse(request, "login.html", {"user": user, "error": ""})',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 current_user 抛出 AuthError，user 设成 None，显示表单。'},{at:'@app.post("/login", response_class=HTMLResponse)',to:'def login_form(',text:'处理登录表单，Form("") 表示参数从表单字段里读取。'},{at:'try:',to:'token, _ = auth.login(username.strip(), password)',text:'点的是“注册”时先注册，然后登录。'},{at:'except auth.AuthError as e:',to:'status_code=e.status)',text:'业务错误就带着状态码重新显示登录页。'},{at:'response = RedirectResponse("/", status_code=303)',to:'return response',text:'登录成功：创建一个 303 重定向响应，Cookie 设置在它上面，再返回它。'},{at:'@app.post("/logout")',to:'return response',text:'退出：删掉会话和 Cookie，回到首页。'},{at:'<!-- templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'{% if user %}',to:'<form method="post" action="/logout"><button>退出</button></form>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'{% else %}',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'{% if error %}',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}]}},'template-java':{body:'模板渲染不写前端 JS，登录、注册、退出都用普通的 HTML 表单提交：表单用 POST 方式提交到后端，后端调用和 JSON 接口同一个业务逻辑层，成功后设置 Cookie，再让浏览器“重定向”（跳转）回首页；失败时重新显示登录页和错误信息。\n重定向用 303 See Other：它告诉浏览器“去用 GET 打开另一个地址”。这样用户刷新首页时，不会弹出“是否重新提交表单”。这种“提交后重定向”的做法有个名字：PRG（Post/Redirect/Get）。\n会话 Cookie 是 SameSite=Lax 的，别的网站偷偷向 /login、/logout 提交表单时，浏览器不会带上它，可以防住大部分 CSRF 攻击。',practice:{steps:['新建 controller/LoginPageController.java，补完 TODO。','新建 templates/login.html，在首页模板里加上入口链接。','打开 /login 注册一个新账号，回到首页；再打开 /login 能看到“你好”和退出按钮；故意输错密码看看提示。'],expect:'登录 / 注册\n[用户名      ]\n[密码        ]\n[登录] [注册]'},code:'// controller/LoginPageController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.*;\n\n@Controller\npublic class LoginPageController {\n\n    private final AuthService auth;\n\n    public LoginPageController(AuthService auth) {\n        this.auth = auth;\n    }\n\n    private static String cookie(String value, long maxAge) {\n        return ResponseCookie.from("session", value)\n            .httpOnly(true).sameSite("Lax").path("/").maxAge(maxAge).build().toString();\n    }\n\n    @GetMapping("/login")\n    public String page(@CookieValue(name = "session", required = false) String token, Model model) {\n        try {\n            model.addAttribute("user", auth.currentUser(token));\n        } catch (AuthService.AuthException e) {\n            model.addAttribute("user", null);\n        }\n        return "login";\n    }\n\n    @PostMapping("/login")\n    public String submit(@RequestParam(defaultValue = "") String username,\n                         @RequestParam(defaultValue = "") String password,\n                         @RequestParam(defaultValue = "login") String action,\n                         Model model, HttpServletResponse response) {\n        // TODO 1：action 是 "register" 时先 auth.register；然后 auth.login（用户名去掉首尾空格）\n        // TODO 2：成功时在 response 上加 Set-Cookie 头，状态码设成 303，Location 头设成 "/"，返回 null（不渲染模板）\n        // TODO 3：捕获 AuthService.AuthException：状态码设成 e.status，model 里放 user（null）和 error，返回 "login"\n        return "login";\n    }\n\n    @PostMapping("/logout")\n    public void logout(@CookieValue(name = "session", required = false) String token, HttpServletResponse response) {\n        // TODO 4：auth.logout(token)，加上删除 Cookie 的 Set-Cookie 头（cookie("", 0)），303 重定向到首页\n    }\n}\n\n<!-- templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN" xmlns:th="http://www.thymeleaf.org">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <div th:if="${user != null}">\n    <p th:text="|你好，${user.username()}|">你好</p>\n    <form method="post" action="/logout"><button>退出</button></form>\n  </div>\n  <div th:if="${user == null}">\n    <h1>登录 / 注册</h1>\n    <form method="post" action="/login">\n      <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n      <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n      <button name="action" value="login">登录</button>\n      <button name="action" value="register">注册</button>\n    </form>\n    <p th:if="${error != null}" th:text="${error}">错误</p>\n  </div>\n</body>\n</html>\n\n<!-- templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// controller/LoginPageController.java',to:'import org.springframework.web.bind.annotation.*;',text:'登录页的控制器，返回页面而不是 JSON，所以用 @Controller。'},{at:'@Controller',to:'this.auth = auth;',text:'注入和 JSON 接口同一个业务逻辑层。'},{at:'private static String cookie(',to:'.httpOnly(true).sameSite("Lax").path("/").maxAge(maxAge).build().toString();',text:'生成 Set-Cookie 响应头的值，选项和 API 的登录一样。'},{at:'@GetMapping("/login")',to:'return "login";',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 currentUser 抛出 AuthException，user 设成 null，显示表单。'},{at:'@PostMapping("/login")',to:'return "login";',text:'处理登录表单，要你补全。'},{at:'@PostMapping("/logout")',to:'public void logout(',text:'处理退出表单，要你补全。'},{at:'<!-- templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'<div th:if="${user != null}">',to:'</div>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'<div th:if="${user == null}">',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login，@RequestParam 同样能读到。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'<p th:if="${error != null}" th:text="${error}">错误</p>',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}],solution:{code:'// controller/LoginPageController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.ResponseCookie;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.*;\n\n@Controller\npublic class LoginPageController {\n\n    private final AuthService auth;\n\n    public LoginPageController(AuthService auth) {\n        this.auth = auth;\n    }\n\n    private static String cookie(String value, long maxAge) {\n        return ResponseCookie.from("session", value)\n            .httpOnly(true).sameSite("Lax").path("/").maxAge(maxAge).build().toString();\n    }\n\n    @GetMapping("/login")\n    public String page(@CookieValue(name = "session", required = false) String token, Model model) {\n        try {\n            model.addAttribute("user", auth.currentUser(token));\n        } catch (AuthService.AuthException e) {\n            model.addAttribute("user", null);\n        }\n        return "login";\n    }\n\n    @PostMapping("/login")\n    public String submit(@RequestParam(defaultValue = "") String username,\n                         @RequestParam(defaultValue = "") String password,\n                         @RequestParam(defaultValue = "login") String action,\n                         Model model, HttpServletResponse response) {\n        try {\n            if (action.equals("register")) {\n                auth.register(username.strip(), password);\n            }\n            AuthService.Login result = auth.login(username.strip(), password);\n            response.addHeader(HttpHeaders.SET_COOKIE, cookie(result.token(), AuthService.SESSION_TTL.toSeconds()));\n            response.setStatus(303);\n            response.setHeader(HttpHeaders.LOCATION, "/");\n            return null;\n        } catch (AuthService.AuthException e) {\n            response.setStatus(e.status);\n            model.addAttribute("user", null);\n            model.addAttribute("error", e.getMessage());\n            return "login";\n        }\n    }\n\n    @PostMapping("/logout")\n    public void logout(@CookieValue(name = "session", required = false) String token, HttpServletResponse response) {\n        auth.logout(token);\n        response.addHeader(HttpHeaders.SET_COOKIE, cookie("", 0));\n        response.setStatus(303);\n        response.setHeader(HttpHeaders.LOCATION, "/");\n    }\n}\n\n<!-- templates/login.html -->\n<!DOCTYPE html>\n<html lang="zh-CN" xmlns:th="http://www.thymeleaf.org">\n<head>\n  <meta charset="utf-8">\n  <title>登录 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <div th:if="${user != null}">\n    <p th:text="|你好，${user.username()}|">你好</p>\n    <form method="post" action="/logout"><button>退出</button></form>\n  </div>\n  <div th:if="${user == null}">\n    <h1>登录 / 注册</h1>\n    <form method="post" action="/login">\n      <p><input name="username" placeholder="用户名（3–20 个字母、数字或下划线）" required></p>\n      <p><input name="password" type="password" placeholder="密码（至少 8 位）" required></p>\n      <button name="action" value="login">登录</button>\n      <button name="action" value="register">注册</button>\n    </form>\n    <p th:if="${error != null}" th:text="${error}">错误</p>\n  </div>\n</body>\n</html>\n\n<!-- templates/index.html：在 <h1> 下面加一行 -->\n<p><a href="/login">登录 / 我的账号</a></p>',explain:[{at:'// controller/LoginPageController.java',to:'import org.springframework.web.bind.annotation.*;',text:'登录页的控制器，返回页面而不是 JSON，所以用 @Controller。'},{at:'@Controller',to:'this.auth = auth;',text:'注入和 JSON 接口同一个业务逻辑层。'},{at:'private static String cookie(',to:'.httpOnly(true).sameSite("Lax").path("/").maxAge(maxAge).build().toString();',text:'生成 Set-Cookie 响应头的值，选项和 API 的登录一样。'},{at:'@GetMapping("/login")',to:'return "login";',text:'登录页：已经登录时把用户交给模板，显示“你好”和退出按钮；没登录时 currentUser 抛出 AuthException，user 设成 null，显示表单。'},{at:'@PostMapping("/login")',to:'Model model, HttpServletResponse response) {',text:'表单字段用 @RequestParam 读取，没填时用默认值。'},{at:'try {',to:'AuthService.Login result = auth.login(username.strip(), password);',text:'点的是“注册”时先注册，然后登录。'},{at:'response.addHeader(HttpHeaders.SET_COOKIE,',to:'return null;',text:'登录成功：设置 Cookie，303 重定向回首页。返回 null 表示我们已经自己写好了响应，不需要渲染模板。'},{at:'} catch (AuthService.AuthException e) {',to:'return "login";',text:'业务错误就带着状态码重新显示登录页。'},{at:'@PostMapping("/logout")',to:'response.setHeader(HttpHeaders.LOCATION, "/");',text:'退出：删掉会话和 Cookie，回到首页。'},{at:'<!-- templates/login.html -->',to:'</head>',text:'登录页模板。'},{at:'<body>',to:'<p><a href="/">← 返回题库</a></p>',text:'返回链接。'},{at:'<div th:if="${user != null}">',to:'</div>',text:'已登录：显示用户名和退出按钮。退出要用 POST 表单，而不是普通链接：链接是 GET 请求，别的网站放一张图片指向它，就能让你在不知情的情况下退出。'},{at:'<div th:if="${user == null}">',to:'</form>',text:'没登录：method="post" 的表单提交时，浏览器把输入框的值编码进请求正文，发到 /login，@RequestParam 同样能读到。两个按钮的 name 都是 action，值不同，后端据此判断是登录还是注册。'},{at:'<p th:if="${error != null}" th:text="${error}">错误</p>',to:'</html>',text:'有错误时显示出来。'},{at:'<!-- templates/index.html：在 <h1> 下面加一行 -->',to:'<p><a href="/login">登录 / 我的账号</a></p>',text:'首页加一个入口。'}]}}}},
  {title:'验收：账号接口',body:'验收脚本会用一个随机的用户名注册（所以可以反复运行），然后把注册、登录、查看当前用户、退出走一遍，还会故意做错几次：重复注册、用户名太短、密码太短、密码错误、没登录就访问。\n脚本用 Python 的 http.cookiejar 模拟浏览器保存和发送 Cookie。最后一项最关键：退出以后，脚本会拿着“退出前的旧令牌”再请求一次 /api/me，必须返回 401。这能检查出“只让浏览器删了 Cookie，服务器那边的会话还有效”这种常见的漏洞。\n页面上的登录、注册、退出，脚本检查不到，要自己点一遍。',practice:{steps:['保持服务在运行。','把下面的脚本保存为 checks/check_l9.py，运行 python checks/check_l9.py，直到全部 ✓。','在页面上亲手注册一个账号、退出、再登录。用 F12 的“应用”（Application）面板看看 Cookie：能看到 session，并且 HttpOnly 那一栏打了勾。','全部通过后提交：git add . 然后 git commit -m "第 9 关：注册、登录和会话"。'],expect:'✓ 健康检查仍然正常\n✓ 注册成功返回 201 和用户信息\n✓ 返回内容里没有密码\n✓ 重复注册返回 409\n✓ 用户名或密码不合格返回 400\n✓ 没登录时 /api/me 返回 401\n✓ 密码错误返回 401\n✓ 登录成功并设置 HttpOnly 的会话 Cookie\n✓ 登录后 /api/me 返回当前用户\n✓ 退出后旧的会话令牌失效\n\n通过 10 / 10'},code:`import http.cookiejar
import json
import random
import sys
import urllib.error
import urllib.request

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
jar = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))
passed = 0


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def call(method, path, body=None, headers=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(BASE + path, data=data, method=method,
                                 headers={"Content-Type": "application/json", **(headers or {})})
    try:
        with opener.open(req, timeout=10) as r:
            status, resp_headers, raw = r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        status, resp_headers, raw = e.code, e.headers, e.read()
    except OSError as e:
        sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
    try:
        result = json.loads(raw.decode("utf-8") or "null")
    except ValueError:
        result = None
    return status, resp_headers, result if isinstance(result, dict) else {}


name = f"user_{random.randint(100000, 999999)}"
password = "password123"

status, _, data = call("GET", "/api/health")
check("健康检查仍然正常", status == 200 and data == {"status": "ok"})

status, _, data = call("POST", "/api/register", {"username": name, "password": password})
check("注册成功返回 201 和用户信息", status == 201 and data.get("username") == name and isinstance(data.get("id"), int))
check("返回内容里没有密码", set(data) == {"id", "username"})
status, _, _ = call("POST", "/api/register", {"username": name, "password": password})
check("重复注册返回 409", status == 409)
bad = [call("POST", "/api/register", body)[0] for body in (
    {"username": "ab", "password": password},
    {"username": "bad name!", "password": password},
    {"username": name + "x", "password": "short"},
    {"username": name + "y"},
)]
check("用户名或密码不合格返回 400", bad == [400, 400, 400, 400])

status, _, _ = call("GET", "/api/me")
check("没登录时 /api/me 返回 401", status == 401)
status, _, _ = call("POST", "/api/login", {"username": name, "password": "wrong-password"})
check("密码错误返回 401", status == 401)

status, headers, _ = call("POST", "/api/login", {"username": name, "password": password})
cookie = headers.get("Set-Cookie") or ""
check("登录成功并设置 HttpOnly 的会话 Cookie", status == 200 and "session=" in cookie and "httponly" in cookie.lower())
status, _, data = call("GET", "/api/me")
check("登录后 /api/me 返回当前用户", status == 200 and data.get("username") == name)

token = next((c.value for c in jar if c.name == "session"), "")
call("POST", "/api/logout")
status, _, _ = call("GET", "/api/me", headers={"Cookie": f"session={token}"})
check("退出后旧的会话令牌失效", bool(token) and status == 401)

print(f"\\n通过 {passed} / 10")`,explain:[{at:'import http.cookiejar',to:'import urllib.request',text:'http.cookiejar 用来像浏览器一样保存 Cookie；random 生成随机的用户名。'},{at:'BASE = sys.argv[1]',text:'服务地址。'},{at:'jar = http.cookiejar.CookieJar()',to:'opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))',text:'创建一个“Cookie 罐子”，再创建一个会自动使用它的请求工具 opener：响应里的 Set-Cookie 会存进罐子，之后的请求自动带上。'},{at:'passed = 0',text:'通过数。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def call(method, path, body=None, headers=None):',to:'headers={"Content-Type": "application/json", **(headers or {})})',text:'发请求：可以指定方法（GET、POST），body 会转成 JSON 放进请求正文，还可以额外加请求头。'},{at:'try:',to:'sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")',text:'用 opener 发请求，拿到状态码、响应头和正文。'},{at:'try:',to:'return status, resp_headers, result if isinstance(result, dict) else {}',text:'把正文解析成 JSON；不是对象（比如 204 没有正文）时返回空字典，后面用 .get 就不会出错。'},{at:'name = f"user_{random.randint(100000, 999999)}"',to:'password = "password123"',text:'每次运行用一个新的随机用户名，脚本可以反复运行。'},{at:'status, _, data = call("GET", "/api/health")',to:'check("健康检查仍然正常"',text:'健康检查。'},{at:'status, _, data = call("POST", "/api/register", {"username": name, "password": password})',to:'check("返回内容里没有密码", set(data) == {"id", "username"})',text:'注册成功返回 201，正文只有 id 和 username 两个字段，密码和哈希值都不能返回。'},{at:'status, _, _ = call("POST", "/api/register", {"username": name, "password": password})',to:'check("重复注册返回 409", status == 409)',text:'同一个用户名再注册一次，返回 409。'},{at:'bad = [',to:'check("用户名或密码不合格返回 400"',text:'四种不合格的情况：用户名太短、用户名有空格和感叹号、密码太短、没传密码，都返回 400。'},{at:'status, _, _ = call("GET", "/api/me")',to:'check("没登录时 /api/me 返回 401", status == 401)',text:'还没登录，罐子里没有 Cookie，返回 401。'},{at:'status, _, _ = call("POST", "/api/login", {"username": name, "password": "wrong-password"})',to:'check("密码错误返回 401", status == 401)',text:'密码错误返回 401。'},{at:'status, headers, _ = call("POST", "/api/login", {"username": name, "password": password})',to:'check("登录成功并设置 HttpOnly 的会话 Cookie"',text:'登录成功，响应头 Set-Cookie 里要有 session=…，并且带 HttpOnly。'},{at:'status, _, data = call("GET", "/api/me")',to:'check("登录后 /api/me 返回当前用户"',text:'这次请求自动带上了 Cookie，返回当前用户。'},{at:'token = next((c.value for c in jar if c.name == "session"), "")',text:'从罐子里取出会话令牌，留着退出后再用。next(…, "") 取第一个符合条件的值，没有就是空字符串。'},{at:'call("POST", "/api/logout")',to:'check("退出后旧的会话令牌失效"',text:'退出后，手动带上旧令牌再请求一次，服务器那边的会话必须已经删掉了。'},{at:'print(f"\\n通过 {passed} / 10")',text:'打印总的通过数。'}]},
  {title:'这一关学到了什么',body:'一、密码只存慢哈希（bcrypt、scrypt），每个密码带随机盐；登录时用同样的方法再算一遍来核对；\n二、HTTP 无状态，靠会话记住“你是谁”：服务器保存“令牌 → 用户”，浏览器用 Cookie 带上令牌；\n三、会话 Cookie 要加 HttpOnly 和 SameSite，上线后再加 Secure；令牌用密码学安全的随机数生成；\n四、退出时既要删服务器上的会话，也要让浏览器删掉 Cookie；\n五、登录失败统一提示“用户名或密码错误”，不暴露哪些用户名已注册；\n六、业务逻辑层出现了：规则集中在一处，JSON 接口和模板页面都调用它，结果一致。\n下一关就用上“当前用户”：记录每个人的学习进度和每日打卡。'}
 ],quiz:[
 {id:'pj-auth-1',q:'数据库里保存用户密码，正确的做法是？',options:['用慢哈希加随机盐后再保存','直接保存明文，方便找回密码','用 MD5 算一遍之后再保存','用能解密的算法加密后保存'],why:['','数据库一旦泄露，所有密码直接暴露。','MD5 算得太快，坏人每秒能试几十亿次，而且没有盐。','能解密就意味着密钥泄露时密码也会泄露，密码只需要“核对”，不需要“还原”。'],answer:0,explain:'密码只存慢哈希：故意算得慢，暴力破解成本很高；每个密码一个随机盐，相同的密码存下来也不一样。登录时用同样的方法再算一遍来核对。'},
 {id:'pj-auth-2',type:'judge',q:'HTTP 协议本身会记住同一个用户的前后请求，所以登录后服务器自然知道是谁。',answer:false,explain:'错误。HTTP 是无状态的，每个请求都是独立的。服务器要靠会话：登录后发给浏览器一个令牌（放在 Cookie 里），之后每个请求带上它，服务器据此找到用户。'},
 {id:'pj-auth-3',q:'会话 Cookie 加上 HttpOnly，主要能防住什么？',options:['XSS 时坏脚本读不到会话令牌','密码在传输途中被别人偷看','用户离开时忘记了退出登录','别的网站读取我们接口的数据'],why:['','防传输被偷看要靠 HTTPS，对应的 Cookie 选项是 Secure。','和忘记退出无关，那要靠会话过期时间。','这是浏览器同源策略管的事。'],answer:0,explain:'HttpOnly 的 Cookie 只会随请求发送，页面上的 JavaScript（document.cookie）读不到，就算被注入了恶意脚本，令牌也偷不走。'},
 {id:'pj-auth-4',q:'用户名正确但密码错误时，登录接口最合适的提示是？',options:['统一说“用户名或密码错误”','提示“密码错误”，方便用户重新输入','提示“这个用户名不存在”','返回 200 和一条提示'],why:['','这样坏人就知道这个用户名确实注册过。','同样会暴露哪些用户名不存在。','登录失败应该返回 401。'],answer:0,explain:'分别提示会让坏人利用登录接口试出哪些用户名已经注册，再针对这些账号猜密码。统一提示更安全。'},
 {id:'pj-auth-5',type:'multi',q:'关于这一关的会话令牌，下面说法正确的有？（多选）',options:['要用密码学安全的随机数生成','要足够长，让人猜不到','服务器记下它的用户和过期时间','可以直接用用户 id 当令牌'],why:['','','','用户 id 很容易猜，别人改一下 Cookie 就能冒充别人。'],answers:[0,1,2],explain:'令牌等同于“临时密码”，必须无法预测：用 crypto/rand、crypto.randomBytes、secrets、SecureRandom 生成，32 字节以上。服务器在 sessions 表里记下它对应的用户和过期时间。'},
 {id:'pj-auth-6',q:'用户名已被注册时，注册接口应该返回哪个状态码？',options:['409（冲突）','401（未认证）','404（不存在）','500（服务器出错）'],why:['','401 表示没有登录或者认证失败。','404 表示资源不存在，这里正好相反，是“已经存在”。','这不是服务器出错，是正常的业务情况。'],answer:0,explain:'409 表示请求和已有的数据冲突。前端看到 409 就能提示“换一个用户名”。'},
 {id:'pj-auth-7',type:'judge',q:'退出登录时，只要让浏览器删掉 Cookie 就够了，服务器上的会话可以不管。',answer:false,explain:'错误。如果令牌之前被人偷走了，服务器上的会话还在，坏人仍然可以用它登录。退出时一定要删掉服务器上的会话，验收脚本最后一项就是检查这个。'},
 {id:'pj-auth-8',type:'fill',q:'只在 HTTPS 连接里发送 Cookie 的那个选项，名字是 ＿。',accepted:['Secure','secure'],explain:'Secure。我们本地开发用的是 HTTP，暂时不加；第 18 关配好 HTTPS 后，会话 Cookie 要加上它。'},
 {id:'pj-auth-9',type:'short',q:'这一关为什么要把“注册、登录”的规则放进单独的业务逻辑层，而不是直接写在处理请求的函数里？',reference:'业务规则（检查格式、哈希密码、核对密码、生成会话）和 HTTP 无关。放在业务逻辑层，JSON 接口和模板页面的表单都能调用同一份规则，结果一致；以后第三方登录也能复用；还可以不启动 HTTP 服务就单独测试这些规则。处理请求的层只负责读参数、读写 Cookie、把错误翻译成状态码。',points:['业务规则和 HTTP 细节分开','多个入口（接口、页面表单、第三方登录）复用同一份规则','方便单独测试，处理请求的层只做翻译'],explain:'这就是第 4 关讲的“厨师”这一层。'},
 {id:'pj-auth-go-1',stack:'go',q:'Go 中给 User 的 PasswordHash 字段加上 json:"-" 标签，作用是？',options:['JSON 里跳过它，接口不泄露哈希','数据库里把这个字段加密保存','让这个字段变成只读、不能改','JSON 里的字段名变成一个横线'],why:['','json 标签只影响 JSON 的转换，和数据库无关。','Go 的标签不控制读写权限。','单独一个 - 表示“忽略”，不是字段名。'],answer:0,explain:'json:"-" 告诉 encoding/json 忽略这个字段。就算哪里不小心把整个 User 返回了，密码哈希也不会出现在响应里。'},
 {id:'pj-auth-java-1',stack:'java',q:'为什么这一关只引入 spring-security-crypto，而不是完整的 spring-boot-starter-security？',options:['只需要哈希工具，完整版会拦截接口','完整版的 Spring Security 不支持 bcrypt','spring-security-crypto 运行得更快','完整版必须配合 MySQL 一起使用'],why:['','完整的 Spring Security 当然支持 bcrypt。','和速度无关。','它和用什么数据库无关。'],answer:0,explain:'完整的 Spring Security 一加进来就会默认要求所有请求登录，还要学很多配置。这一关自己实现会话，只借用它的 BCryptPasswordEncoder。'},
 {id:'pj-auth-node-1',stack:'node',q:'Express 中为什么要加 app.use(express.json())？',options:['解析 JSON 请求正文放进 req.body','让所有的响应都变成 JSON 格式','解析请求头里携带的 Cookie','检查请求正文里的密码长度'],why:['','返回 JSON 用的是 res.json。','解析 Cookie 用的是 cookie-parser。','检查规则是业务逻辑层的事。'],answer:0,explain:'Express 默认不解析请求正文，不加这个中间件，req.body 是 undefined，注册和登录就拿不到用户名和密码。'},
 {id:'pj-auth-python-1',stack:'python',q:'FastAPI 中路由函数的参数写成 body: Credentials（Credentials 继承 BaseModel），会发生什么？',options:['把 JSON 正文解析成对象并校验','从地址的查询参数里读取 body','把 Credentials 保存到数据库里','把请求正文原样当作字符串传入'],why:['','BaseModel 类型的参数默认来自请求正文，不是查询参数。','它只负责解析和校验，不保存数据。','FastAPI 会按模型解析并校验类型。'],answer:0,explain:'pydantic 模型声明了正文的格式。字段缺失或类型不对时，FastAPI 抛出 RequestValidationError，我们统一处理成 400。'},
 {id:'pj-auth-html-1',stack:'html',q:'login.js 用 fetch 调用 /api/login 成功后，为什么不需要自己保存令牌？',options:['浏览器自动保存并在之后带上','令牌会自动显示在地址栏里','后端把令牌写进 localStorage','登录之后就不再需要令牌了'],why:['','令牌不会出现在地址里，也不应该放进地址。','后端没法直接写浏览器的 localStorage。','之后每个请求都要靠它识别用户。'],answer:0,explain:'Cookie 由浏览器管理：响应里的 Set-Cookie 会被保存，之后同源请求自动带上。会话 Cookie 还是 HttpOnly 的，JS 本来也读不到它。'},
 {id:'pj-auth-react-1',stack:'react',q:'LoginPage 里“注册”按钮写了 type="button"，原因是？',options:['不提交表单，改由 onClick 处理','让按钮显示成灰色的禁用样式','让这个按钮最多只被点击一次','让浏览器记住刚才输入的密码'],why:['','样式和 type 无关。','type 不限制点击次数。','和记住密码无关。'],answer:0,explain:'表单里的按钮默认 type="submit"，点了会提交表单（这里提交表单执行的是登录）。写成 type="button" 后它只是一个普通按钮，由 onClick 调用注册。'},
 {id:'pj-auth-template-go-1',stack:'template-go',q:'登录表单提交成功后，用 http.Redirect(w, r, "/", http.StatusSeeOther) 的好处是？',options:['改用 GET 打开首页，刷新不重复提交','303 会让 Cookie 立刻就过期','303 会让首页加载得更快一些','不重定向的话 Cookie 设置不上'],why:['','303 和 Cookie 的有效期无关。','和速度无关。','Cookie 在 POST 的响应里就能设置，和是否重定向无关。'],answer:0,explain:'这是 PRG（Post/Redirect/Get）：处理完 POST 后让浏览器去 GET 另一个地址。用户刷新页面时刷新的是那个 GET 请求，不会弹出“是否重新提交表单”。'},
 {id:'pj-auth-template-java-1',stack:'template-java',q:'退出为什么做成 <form method="post" action="/logout">，而不是一个 <a href="/logout"> 链接？',options:['GET 链接容易被别的网站偷偷触发','普通链接的请求没法携带 Cookie','Thymeleaf 模板里不支持写链接','POST 请求比 GET 请求更快一些'],why:['','链接请求同样会带上 Cookie，这正是问题所在。','Thymeleaf 当然可以写链接。','速度没有区别。'],answer:0,explain:'会改变状态的操作（退出、删除、提交）都应该用 POST。GET 请求很容易被别的网站触发（图片、链接预加载），而 SameSite=Lax 的 Cookie 在跨站 POST 时不会被带上。'},
 {id:'pj-auth-template-node-1',stack:'template-node',q:'处理登录表单时为什么要加 app.use(express.urlencoded({ extended: false }))？',options:['解析 a=1&b=2 格式的表单正文','它负责把模板页面渲染成 HTML','它负责检查当前用户有没有登录','它负责加密表单里提交的密码'],why:['','渲染页面用的是 res.render 和 EJS。','检查登录是业务逻辑层的 currentUser。','密码在业务逻辑层做哈希。'],answer:0,explain:'HTML 表单默认用 application/x-www-form-urlencoded 格式提交，和 JSON 不一样，需要 express.urlencoded 解析后放进 req.body。'},
 {id:'pj-auth-template-python-1',stack:'template-python',q:'FastAPI 中用 Form("") 读取表单字段之前，需要先安装哪个库？',options:['python-multipart','jinja2（模板引擎）','uvicorn（服务器）','pydantic（校验）'],why:['','jinja2 是模板引擎，第 5 关已经装了。','uvicorn 是运行服务的服务器。','pydantic 是 FastAPI 自带的依赖，用来解析 JSON 模型。'],answer:0,explain:'FastAPI 解析表单格式的请求正文依赖 python-multipart，没装时启动会报错提示安装。'},
]};
